@import "@fontsource/rajdhani/400.css";
@import "@fontsource/rajdhani/500.css";
@import "@fontsource/rajdhani/600.css";
@import "@fontsource/rajdhani/700.css";
@import "@fontsource/share-tech-mono/400.css";

:root {
  --ink: #05070a;
  --ink-2: #090d12;
  --panel: rgba(8, 13, 18, 0.76);
  --panel-solid: #0a0f15;
  --paper: #e9eef2;
  --muted: #81909d;
  --muted-2: #53616c;
  --orange: #ff5a2d;
  --orange-hot: #ff8a45;
  --amber: #ffb45c;
  --cyan: #5ee7ff;
  --cyan-dim: #2a8092;
  --red: #ff304c;
  --green: #7fffb2;
  --line: rgba(255, 255, 255, 0.14);
  --line-soft: rgba(255, 255, 255, 0.07);
  --display: "Rajdhani", "Arial Narrow", sans-serif;
  --mono: "Share Tech Mono", "Lucida Console", monospace;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--paper);
  font-family: var(--display);
  -webkit-font-smoothing: antialiased;
  overscroll-behavior: none;
}

body {
  user-select: none;
  -webkit-user-select: none;
  touch-action: none;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

#app {
  position: relative;
  width: 100%;
  height: 100%;
  height: 100dvh;
  overflow: hidden;
  isolation: isolate;
}

#game-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
}

.screen {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.hidden {
  display: none !important;
}

/* ═══════════════════ SCREEN FX ═══════════════════ */
.screen-fx {
  position: absolute;
  inset: 0;
  z-index: 8;
  pointer-events: none;
  overflow: hidden;
}

.vignette {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 50% 45%, transparent 38%, rgba(0, 0, 0, 0.22) 72%, rgba(0, 0, 0, 0.64) 100%),
    linear-gradient(180deg, rgba(0, 0, 0, 0.3), transparent 24%, transparent 72%, rgba(0, 0, 0, 0.48));
}

.scanlines {
  position: absolute;
  inset: 0;
  opacity: 0.28;
  background: repeating-linear-gradient(
    180deg,
    transparent 0,
    transparent 2px,
    rgba(0, 0, 0, 0.22) 3px,
    transparent 4px
  );
  mix-blend-mode: multiply;
}

.grain {
  position: absolute;
  inset: -50%;
  opacity: 0.045;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.8'/%3E%3C/svg%3E");
  animation: grainShift 0.24s steps(2) infinite;
}

@keyframes grainShift {
  0% { transform: translate(0, 0); }
  25% { transform: translate(2%, -1%); }
  50% { transform: translate(-1%, 2%); }
  75% { transform: translate(1%, 1%); }
  100% { transform: translate(-2%, 0); }
}

#damage-vignette {
  position: absolute;
  inset: 0;
  opacity: 0;
  background:
    radial-gradient(ellipse at center, transparent 48%, rgba(180, 0, 20, 0.35) 100%),
    linear-gradient(90deg, rgba(255, 20, 40, 0.24), transparent 15%, transparent 85%, rgba(255, 20, 40, 0.24));
  transition: opacity 0.3s ease;
}

#damage-vignette.flash {
  opacity: 1;
  animation: damagePulse 0.7s ease-out;
}

@keyframes damagePulse {
  0% { opacity: 1; }
  100% { opacity: 0; }
}

.transition {
  position: absolute;
  inset: 0;
  z-index: 100;
  background: #020305;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.38s ease;
}

.transition.active {
  opacity: 1;
}

.is-loading .menu-screen {
  opacity: 0;
}

.menu-screen {
  opacity: 1;
  transition: opacity 0.6s ease;
}

/* ═══════════════════ MENU ═══════════════════ */
.menu-screen {
  z-index: 5;
  display: flex;
  flex-direction: column;
  padding: calc(26px + var(--safe-top)) clamp(28px, 4.2vw, 72px) calc(17px + var(--safe-bottom));
  background:
    linear-gradient(95deg, rgba(3, 5, 8, 0.95) 0%, rgba(3, 5, 8, 0.72) 34%, rgba(4, 7, 10, 0.12) 67%, rgba(4, 7, 10, 0.34) 100%),
    linear-gradient(180deg, rgba(3, 5, 8, 0.55), transparent 28%, transparent 77%, rgba(3, 5, 8, 0.86));
}

.menu-screen::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(90deg, transparent calc(50% - 1px), rgba(255, 255, 255, 0.035) 50%, transparent calc(50% + 1px)),
    radial-gradient(circle at 78% 48%, rgba(255, 91, 42, 0.08), transparent 35%);
  mask-image: linear-gradient(180deg, transparent, #000 30%, #000 70%, transparent);
}

.menu-header {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 26px;
  min-height: 47px;
  border-bottom: 1px solid var(--line-soft);
  padding-bottom: 18px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}

.brand-mark {
  width: 37px;
  height: 37px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3px;
  transform: skewX(-11deg);
}

.brand-mark i {
  display: block;
  background: var(--paper);
}

.brand-mark i:nth-child(1) {
  height: 56%;
  align-self: end;
}

.brand-mark i:nth-child(2) {
  height: 100%;
  background: var(--orange);
}

.brand-mark i:nth-child(3) {
  height: 78%;
  align-self: center;
}

.brand-type {
  font-family: var(--mono);
  font-size: 8px;
  line-height: 1.35;
  letter-spacing: 0.15em;
  color: var(--muted);
}

.menu-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.17em;
  color: var(--muted);
}

.menu-meta-sep {
  color: var(--muted-2);
}

.live-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--orange);
  box-shadow: 0 0 0 0 rgba(255, 90, 45, 0.6);
  animation: livePulse 1.8s infinite;
}

@keyframes livePulse {
  0% { box-shadow: 0 0 0 0 rgba(255, 90, 45, 0.5); }
  70% { box-shadow: 0 0 0 7px rgba(255, 90, 45, 0); }
  100% { box-shadow: 0 0 0 0 rgba(255, 90, 45, 0); }
}

.menu-wing {
  margin-left: auto;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.16em;
  color: var(--muted);
  white-space: nowrap;
}

.menu-layout {
  position: relative;
  z-index: 2;
  flex: 1;
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(260px, 0.55fr);
  align-items: center;
  gap: clamp(28px, 6vw, 100px);
  min-height: 0;
  padding: clamp(24px, 5vh, 70px) 0 clamp(18px, 4vh, 50px);
}

.menu-copy {
  max-width: 760px;
  animation: menuCopyIn 0.9s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

@keyframes menuCopyIn {
  from { opacity: 0; transform: translateY(18px); }
  to { opacity: 1; transform: translateY(0); }
}

.eyebrow,
.panel-kicker {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--orange);
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 13px;
  margin-bottom: clamp(10px, 1.2vh, 16px);
}

.eyebrow::before {
  content: "";
  width: 33px;
  height: 1px;
  background: var(--orange);
}

.eyebrow span {
  color: var(--muted);
}

.logo {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  line-height: 0.79;
  letter-spacing: -0.045em;
  text-transform: uppercase;
  font-weight: 700;
  font-size: clamp(74px, 10.8vw, 174px);
  filter: drop-shadow(0 13px 30px rgba(0, 0, 0, 0.5));
}

.logo-rotor {
  color: var(--paper);
}

.logo-slash {
  font-size: 0.52em;
  color: var(--orange);
  letter-spacing: -0.1em;
  margin: 0 0.07em;
  transform: translateY(-0.12em);
}

.logo-titan {
  position: relative;
  color: transparent;
  -webkit-text-stroke: clamp(1px, 0.11vw, 2px) var(--paper);
  text-shadow: 0 0 24px rgba(255, 255, 255, 0.09);
}

.logo-titan::before,
.logo-titan::after {
  content: attr(data-text);
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.logo-titan::before {
  color: var(--orange);
  -webkit-text-stroke: 0;
  clip-path: inset(64% 0 23% 0);
  opacity: 0.88;
  transform: translateX(2px);
}

.logo-titan::after {
  color: transparent;
  -webkit-text-stroke: 1px rgba(94, 231, 255, 0.55);
  opacity: 0.36;
  transform: translate(4px, -2px);
  clip-path: inset(19% 0 72% 0);
}

.tagline {
  margin-top: clamp(20px, 3.2vh, 34px);
  font-size: clamp(23px, 2.05vw, 35px);
  line-height: 1.04;
  font-weight: 400;
  letter-spacing: 0.015em;
  text-transform: uppercase;
  color: #b8c2ca;
}

.tagline b {
  font-weight: 600;
  color: var(--paper);
}

.deck {
  max-width: 488px;
  margin-top: 15px;
  font-family: var(--mono);
  font-size: 10.5px;
  line-height: 1.7;
  letter-spacing: 0.02em;
  color: #84939e;
}

.menu-actions {
  display: flex;
  align-items: stretch;
  gap: 11px;
  margin-top: clamp(22px, 3.2vh, 34px);
}

.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  min-height: 54px;
  padding: 0 25px;
  font-family: var(--display);
