  color: var(--muted);
}

.control-strip span:last-child {
  margin-left: 4px;
}

kbd {
  display: inline-grid;
  place-items: center;
  min-width: 19px;
  height: 19px;
  padding: 0 5px;
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 400;
  color: #b9c3cb;
  border: 1px solid rgba(255, 255, 255, 0.2);
  background: rgba(255, 255, 255, 0.03);
  border-radius: 2px;
  box-shadow: inset 0 -1px 0 rgba(0, 0, 0, 0.4);
}

.mouse-icon {
  width: 13px;
  height: 18px;
  border: 1px solid rgba(255, 255, 255, 0.3);
  border-radius: 7px;
  position: relative;
}

.mouse-icon::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 3px;
  width: 1px;
  height: 5px;
  background: var(--orange);
  transform: translateX(-50%);
}

/* menu side */
.menu-side {
  align-self: end;
  display: flex;
  flex-direction: column;
  gap: 20px;
  padding-bottom: clamp(8px, 3vh, 40px);
  animation: menuSideIn 1s 0.2s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

@keyframes menuSideIn {
  from { opacity: 0; transform: translateX(16px); }
  to { opacity: 1; transform: translateX(0); }
}

.side-rule {
  width: 100%;
  height: 1px;
  background: linear-gradient(90deg, var(--orange), rgba(255, 255, 255, 0.08));
  position: relative;
}

.side-rule::before {
  content: "";
  position: absolute;
  left: 0;
  top: -3px;
  width: 7px;
  height: 7px;
  background: var(--orange);
  transform: rotate(45deg);
}

.threat-panel,
.mission-panel {
  border: 1px solid var(--line-soft);
  background: linear-gradient(135deg, rgba(9, 14, 19, 0.82), rgba(5, 8, 12, 0.4));
  backdrop-filter: blur(8px);
  padding: 18px;
}

.threat-panel {
  border-left: 1px solid rgba(255, 90, 45, 0.65);
}

.panel-kicker {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 8px;
  color: var(--muted);
}

.blink-square {
  width: 5px;
  height: 5px;
  background: var(--orange);
  animation: blinkSquare 1.3s steps(2) infinite;
}

@keyframes blinkSquare {
  50% { opacity: 0.15; }
}

.threat-name {
  margin-top: 13px;
  font-family: var(--mono);
  font-size: 9px;
  line-height: 1.5;
  letter-spacing: 0.1em;
  color: var(--muted);
}

.threat-name b {
  font-family: var(--display);
  font-size: clamp(28px, 2.4vw, 38px);
  line-height: 1;
  letter-spacing: 0.02em;
  color: var(--paper);
}

.threat-stats {
  display: grid;
  gap: 6px;
  margin: 15px 0;
}

.threat-stats div,
.mission-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.07em;
  color: var(--muted-2);
}

.threat-stats b,
.mission-row b {
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 400;
  color: #9aa8b3;
}

.danger {
  color: var(--orange) !important;
}

.ok {
  color: var(--green) !important;
}

.threat-bars {
  display: flex;
  align-items: flex-end;
  gap: 3px;
  height: 24px;
}

.threat-bars span {
  display: block;
  width: 7px;
  height: calc(var(--w) * 0.23);
  background: linear-gradient(180deg, rgba(255, 90, 45, 0.95), rgba(255, 90, 45, 0.2));
}

.threat-bars span:nth-child(3n) {
  background: linear-gradient(180deg, rgba(94, 231, 255, 0.8), rgba(94, 231, 255, 0.1));
}

.mission-panel {
  display: grid;
  gap: 9px;
}

.mission-panel .panel-kicker {
  margin-bottom: 5px;
}

.best-panel {
  display: flex;
  align-items: baseline;
  gap: 9px;
  padding-top: 4px;
}

.best-panel span {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  color: var(--muted-2);
}

.best-panel b {
  font-size: 25px;
  font-weight: 600;
  color: var(--paper);
  letter-spacing: 0.03em;
}

.best-panel small {
  font-family: var(--mono);
  font-size: 8px;
  color: var(--muted);
}

.menu-footer {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
  padding-top: 14px;
  border-top: 1px solid var(--line-soft);
}

.footer-ticker {
  display: flex;
  align-items: center;
  gap: 13px;
  min-width: 0;
  overflow: hidden;
}

.ticker-label {
  flex-shrink: 0;
  padding: 3px 7px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.1em;
  color: #120b07;
  background: var(--orange);
}

.ticker-track {
  display: flex;
  gap: 49px;
  min-width: max-content;
  animation: ticker 34s linear infinite;
}

.ticker-track span {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.08em;
  color: var(--muted-2);
}

.ticker-track span::before {
  content: "///";
  margin-right: 10px;
  color: rgba(255, 90, 45, 0.5);
}

@keyframes ticker {
  to { transform: translateX(-50%); }
}

.footer-id {
  flex-shrink: 0;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  color: var(--muted-2);
}

/* ═══════════════════ MODALS ═══════════════════ */
.modal-screen {
  z-index: 40;
  display: grid;
  place-items: center;
  padding: calc(20px + var(--safe-top)) calc(20px + var(--safe-right)) calc(20px + var(--safe-bottom)) calc(20px + var(--safe-left));
}

.modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(2, 4, 6, 0.76);
  backdrop-filter: blur(7px) saturate(0.7);
}

.brief-card,
.pause-card,
.gameover-card {
  position: relative;
  width: min(760px, 94vw);
  max-height: 90vh;
  overflow: auto;
  padding: clamp(25px, 4vw, 48px);
  background:
    linear-gradient(135deg, rgba(14, 20, 28, 0.98), rgba(6, 10, 14, 0.97));
  border: 1px solid rgba(255, 255, 255, 0.15);
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.65);
  clip-path: polygon(0 0, calc(100% - 22px) 0, 100% 22px, 100% 100%, 22px 100%, 0 calc(100% - 22px));
}

.brief-card::before,
.pause-card::before,
.gameover-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 90px;
  height: 2px;
  background: var(--orange);
}

.modal-close {
  position: absolute;
  top: 15px;
  right: 19px;
  width: 32px;
  height: 32px;
  font-family: var(--mono);
  font-size: 22px;
  color: var(--muted);
  transition: color 0.2s ease;
}

.modal-close:hover {
  color: var(--paper);
}

.brief-card h2,
.pause-card h2,
.gameover-card h2 {
  margin-top: 12px;
  font-size: clamp(42px, 6vw, 70px);
  line-height: 0.86;
  letter-spacing: -0.02em;
}

.brief-card h2 span {
  color: var(--orange);
}

.brief-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2px;
  margin-top: 27px;
  background: var(--line-soft);
  border: 1px solid var(--line-soft);
}

.brief-item {
  display: flex;
  gap: 13px;
  padding: 17px;
  background: #080d12;
}

.brief-num {
  font-family: var(--mono);
  font-size: 9px;
  color: var(--orange);
}

.brief-item b {
  display: block;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.12em;
  color: var(--paper);
}

.brief-item p {
  margin-top: 6px;
  font-family: var(--mono);
  font-size: 9px;
  line-height: 1.65;
  color: #778590;
}

.brief-item kbd {
  min-width: 16px;
  height: 15px;
  padding: 0 3px;
  font-size: 7px;
  vertical-align: middle;
}

.brief-note {
  margin-top: 22px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.08em;
  color: var(--muted);
}

.brief-note span {
  margin-right: 6px;
  color: var(--orange);
}

/* ═══════════════════ HUD ═══════════════════ */
.hud {
  z-index: 10;
  pointer-events: none;
  font-family: var(--mono);
  text-shadow: 0 1px 6px rgba(0, 0, 0, 0.8);
}

.hud-top {
  position: absolute;
  top: calc(18px + var(--safe-top));
  left: calc(24px + var(--safe-left));
  right: calc(24px + var(--safe-right));
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: start;
  gap: 20px;
}

.hud-brand {
  display: flex;
  align-items: center;
  gap: 10px;
}

.hud-brand-mark {
  width: 18px;
  height: 28px;
  border-left: 4px solid var(--orange);
  border-right: 4px solid var(--paper);
  transform: skewX(-12deg);
  opacity: 0.9;
}

.hud-brand > div {
  font-family: var(--display);
  font-size: 17px;
  font-weight: 700;
  letter-spacing: 0.04em;
}

.hud-brand > div span {
  color: var(--orange);
  margin: 0 2px;
}

.hud-brand small {
  display: block;
  margin-top: 1px;
  font-size: 7px;
  letter-spacing: 0.16em;
  color: var(--muted);
}

.city-status {
  width: min(360px, 36vw);
  padding-top: 3px;
}

.city-label,
.city-sub {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 8px;
  letter-spacing: 0.14em;
  color: #9aa8b3;
}

.city-label b {
  font-size: 11px;
  font-weight: 400;
  color: var(--paper);
}

.city-sub {
  margin-top: 6px;
  color: var(--muted-2);
}

.city-sub span:last-child {
  color: var(--green);
}

.city-sub span:last-child.warn {
  color: var(--orange);
}

.city-sub span:last-child.critical {
  color: var(--red);
  animation: blinkSquare 0.75s steps(2) infinite;
}

.city-bar {
  position: relative;
  height: 6px;
  margin-top: 6px;
  background: rgba(255, 255, 255, 0.12);
  overflow: hidden;
}

.city-bar::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 2;
  background: repeating-linear-gradient(90deg, transparent 0, transparent calc(10% - 1px), rgba(2, 5, 8, 0.6) calc(10% - 1px), rgba(2, 5, 8, 0.6) 10%);
}

.city-bar i {
  display: block;
  height: 100%;
  width: 100%;
  background: linear-gradient(90deg, var(--orange), #ffd48c);
  transition: width 0.4s ease, background 0.4s ease;
  box-shadow: 0 0 15px rgba(255, 90, 45, 0.45);
}

.city-bar i.warn {
  background: linear-gradient(90deg, var(--orange), var(--red));
}

.city-bar i.critical {
  background: var(--red);
}

.hud-score {
  display: flex;
  justify-content: flex-end;
  align-items: flex-start;
  gap: 26px;
}

.hud-score > div > span {
  display: block;
  font-size: 7px;
  letter-spacing: 0.16em;
  color: var(--muted);
}

.hud-score > div > b {
  display: block;
  margin-top: 3px;
  font-family: var(--display);
  font-size: 19px;
  line-height: 1;
  font-weight: 600;
  letter-spacing: 0.09em;
  color: var(--paper);
}

.hud-wave {
  text-align: right;
}

.hud-wave b {
  color: var(--orange) !important;
}

.icon-btn {
  pointer-events: auto;
  margin-top: 2px;
  padding: 5px 7px;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.1em;
  color: var(--muted);
  border: 1px solid var(--line-soft);
}

.icon-btn:hover {
  color: var(--paper);
  border-color: var(--line);
}

.hud-objective {
  position: absolute;
  top: calc(88px + var(--safe-top));
  left: calc(24px + var(--safe-left));
  min-width: 208px;
  padding: 11px 13px 10px;
  background: linear-gradient(90deg, rgba(5, 9, 13, 0.78), rgba(5, 9, 13, 0));
  border-left: 1px solid var(--orange);
}

.objective-kicker {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 7px;
  letter-spacing: 0.14em;
  color: var(--muted);
}

.objective-main {
  margin-top: 5px;
  font-family: var(--display);
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.08em;
}

.objective-sub {
  display: flex;
  gap: 15px;
  margin-top: 3px;
  font-size: 7px;
  letter-spacing: 0.08em;
  color: var(--muted-2);
}

.objective-sub span:first-child {
  color: var(--orange);
}

/* reticle */
.reticle {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 92px;
  height: 92px;
  transform: translate(-50%, -50%);
  transition: opacity 0.2s ease;
}

.reticle-ring {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 56px;
  height: 56px;
  border: 1px solid rgba(255, 255, 255, 0.24);
  border-radius: 50%;
  transform: translate(-50%, -50%);
  transition: width 0.2s ease, height 0.2s ease, border-color 0.16s ease, box-shadow 0.16s ease;
}

.reticle-ring::before {
  content: "";
  position: absolute;
  inset: 8px;
  border: 1px dashed rgba(255, 255, 255, 0.14);
  border-radius: 50%;
  animation: spin 15s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

.reticle-dot {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 8px var(--cyan);
  transform: translate(-50%, -50%);
}

.reticle-tick {
  position: absolute;
  background: rgba(255, 255, 255, 0.56);
}

.reticle-tick.t,
.reticle-tick.b {
  left: 50%;
  width: 1px;
  height: 8px;
  transform: translateX(-50%);
}

.reticle-tick.t { top: 3px; }
.reticle-tick.b { bottom: 3px; }

.reticle-tick.l,
.reticle-tick.r {
  top: 50%;
  width: 8px;
  height: 1px;
  transform: translateY(-50%);
}

.reticle-tick.l { left: 3px; }
.reticle-tick.r { right: 3px; }

.reticle-brackets i {
  position: absolute;
  width: 12px;
  height: 12px;
  border-color: rgba(94, 231, 255, 0.55);
  border-style: solid;
}

.reticle-brackets i:nth-child(1) { left: 7px; top: 7px; border-width: 1px 0 0 1px; }
.reticle-brackets i:nth-child(2) { right: 7px; top: 7px; border-width: 1px 1px 0 0; }
.reticle-brackets i:nth-child(3) { left: 7px; bottom: 7px; border-width: 0 0 1px 1px; }
.reticle-brackets i:nth-child(4) { right: 7px; bottom: 7px; border-width: 0 1px 1px 0; }

.reticle.target .reticle-ring {
  width: 64px;
  height: 64px;
  border-color: rgba(255, 90, 45, 0.85);
  box-shadow: 0 0 18px rgba(255, 90, 45, 0.2), inset 0 0 18px rgba(255, 90, 45, 0.09);
}

.reticle.target .reticle-brackets i {
  border-color: var(--orange);
}

.reticle.overheat .reticle-dot {
  background: var(--red);
  box-shadow: 0 0 8px var(--red);
}

.reticle-label {
  position: absolute;
  left: 50%;
  top: 76px;
  width: max-content;
  transform: translateX(-50%);
  font-size: 7px;
  letter-spacing: 0.14em;
  color: rgba(255, 255, 255, 0.42);
}

.hitmarker {
  position: absolute;
  inset: 0;
  opacity: 0;
}

.hitmarker i {
  position: absolute;
  width: 10px;
  height: 1px;
  background: #fff;
  left: 50%;
  top: 50%;
}

.hitmarker i:nth-child(1) { transform: translate(-17px, -12px) rotate(45deg); }
.hitmarker i:nth-child(2) { transform: translate(7px, -12px) rotate(-45deg); }
.hitmarker i:nth-child(3) { transform: translate(-17px, 11px) rotate(-45deg); }
.hitmarker i:nth-child(4) { transform: translate(7px, 11px) rotate(45deg); }

.hitmarker.show {
  animation: hitmarker 0.26s ease-out;
}

@keyframes hitmarker {
  0% { opacity: 1; transform: scale(1.25); }
  100% { opacity: 0; transform: scale(0.92); }
}

.hitmarker.crit i {
  background: var(--orange);
  box-shadow: 0 0 5px var(--orange);
}

/* target panel */
.target-panel {
  position: absolute;
  top: calc(92px + var(--safe-top));
  right: calc(24px + var(--safe-right));
  width: 212px;
  padding: 11px 12px;
  opacity: 0;
  transform: translateX(8px);
  transition: opacity 0.2s ease, transform 0.2s ease;
  background: linear-gradient(270deg, rgba(6, 10, 14, 0.8), rgba(6, 10, 14, 0));
  border-right: 1px solid var(--orange);
}

.target-panel.active {
  opacity: 1;
  transform: translateX(0);
}

.target-head,
.target-foot {
  display: flex;
  justify-content: space-between;
  font-size: 7px;
  letter-spacing: 0.12em;
  color: var(--muted);
}

.target-head span:first-child {
  color: var(--orange);
}

.target-name {
  margin: 4px 0 6px;
  font-family: var(--display);
  font-size: 17px;
  font-weight: 600;
  letter-spacing: 0.06em;
}

.target-hp {
  height: 4px;
  background: rgba(255, 255, 255, 0.12);
}

.target-hp i {
  display: block;
  width: 100%;
  height: 100%;
  background: var(--orange);
  transition: width 0.15s linear;
}

.target-foot {
  margin-top: 5px;
  color: var(--muted-2);
}

.target-foot b {
  font-weight: 400;
  color: var(--paper);
}

.lockbox {
  position: absolute;
  width: 120px;
  height: 120px;
  opacity: 0;
  transform: translate(-50%, -50%);
  transition: opacity 0.15s ease;
}

.lockbox.active {
  opacity: 0.85;
}

.lock-corner {
  position: absolute;
  width: 22px;
  height: 22px;
  border-color: var(--orange);
  border-style: solid;
}

.lock-corner.tl { left: 0; top: 0; border-width: 1px 0 0 1px; }
.lock-corner.tr { right: 0; top: 0; border-width: 1px 1px 0 0; }
.lock-corner.bl { left: 0; bottom: 0; border-width: 0 0 1px 1px; }
.lock-corner.br { right: 0; bottom: 0; border-width: 0 1px 1px 0; }

.lock-tag {
  position: absolute;
  left: 50%;
  bottom: -15px;
  transform: translateX(-50%);
  padding: 2px 5px;
  background: var(--orange);
  color: #100b08;
  font-size: 7px;
  letter-spacing: 0.12em;
  white-space: nowrap;
}

/* flight hud */
.flight-hud {
  position: absolute;
  left: calc(24px + var(--safe-left));
  bottom: calc(95px + var(--safe-bottom));
  width: 125px;
}

.flight-row {
  display: flex;
  align-items: baseline;
  gap: 5px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  padding: 3px 0;
}

.flight-row span {
  width: 31px;
  font-size: 7px;
  letter-spacing: 0.1em;
  color: var(--muted);
}

.flight-row b {
  font-family: var(--display);
  font-size: 19px;
  font-weight: 500;
  line-height: 1;
  letter-spacing: 0.06em;
}

.flight-row i {
  font-style: normal;
  font-size: 7px;
  color: var(--muted-2);
}

.hull-bar {
  height: 3px;
  margin-top: 5px;
  background: rgba(255, 255, 255, 0.1);
}

.hull-bar i {
  display: block;
  height: 100%;
  width: 100%;
  background: var(--cyan);
  transition: width 0.2s ease, background 0.2s ease;
}

.hull-bar i.warn {
  background: var(--orange);
}

.hull-bar i.critical {
  background: var(--red);
}

.heading {
  margin-top: 6px;
  font-size: 8px;
  letter-spacing: 0.12em;
  color: var(--muted);
}

/* weapon hud */
.weapon-hud {
  position: absolute;
  right: calc(24px + var(--safe-right));
  bottom: calc(95px + var(--safe-bottom));
  width: 232px;
}

.weapon-line {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 0;
  border-top: 1px solid rgba(255, 255, 255, 0.12);
}

.weapon-icon {
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  font-family: var(--display);
  font-size: 18px;
  color: var(--orange);
  border: 1px solid rgba(255, 90, 45, 0.4);
  transform: skewX(-7deg);
}

.weapon-line > div {
  flex: 1;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}

.weapon-line > div span {
  font-size: 7px;
  letter-spacing: 0.1em;
  color: var(--muted);
}

.weapon-line > div b {
  font-family: var(--display);
  font-size: 17px;
  font-weight: 600;
  color: var(--paper);
}

.weapon-line small {
  width: 44px;
  text-align: right;
  font-size: 7px;
  letter-spacing: 0.06em;
  color: var(--muted-2);
}

.missile-line {
  border-top: 1px solid var(--line-soft);
}

.missile-icon {
  color: var(--cyan);
  border-color: rgba(94, 231, 255, 0.4);
}

.missile-line.empty > div b {
  color: var(--orange);
}

.heat-bar {
  position: relative;
  height: 4px;
  margin: 2px 0 6px 28px;
  background: rgba(255, 255, 255, 0.1);
}

.heat-bar i {
  display: block;
  width: 0%;
  height: 100%;
  background: var(--cyan);
  transition: width 0.06s linear;
}

.heat-bar i.hot {
  background: var(--orange);
}

.heat-bar i.over {
  background: var(--red);
}

.heat-bar span {
  position: absolute;
  right: 0;
  top: 6px;
  font-size: 6px;
  letter-spacing: 0.12em;
  color: var(--muted-2);
}

.perks-line {
  border-top: 1px solid var(--line-soft);
  padding-top: 7px;
  gap: 4px;
  flex-wrap: wrap;
}

.perk-chip {
  padding: 2px 5px;
  font-size: 6px;
  letter-spacing: 0.07em;
  color: var(--cyan);
  border: 1px solid rgba(94, 231, 255, 0.22);
  background: rgba(94, 231, 255, 0.04);
}

/* radar */
.radar-wrap {
  position: absolute;
  left: 50%;
  bottom: calc(19px + var(--safe-bottom));
  width: 188px;
  height: 188px;
  transform: translateX(-50%);
  opacity: 0.88;
}

.radar-head {
  display: flex;
  justify-content: space-between;
  font-size: 7px;
  letter-spacing: 0.1em;
  color: var(--muted);
}

.radar-head b {
  font-weight: 400;
  color: var(--muted-2);
}

#radar {
  width: 188px;
  height: 188px;
  margin-top: 3px;
  display: block;
}

.radar-sweep {
  position: absolute;
  left: 50%;
  bottom: 12px;
  width: 94px;
  height: 94px;
  transform-origin: 0 100%;
  background: conic-gradient(from 0deg at 0% 100%, rgba(94, 231, 255, 0), rgba(94, 231, 255, 0.08) 70%, rgba(94, 231, 255, 0.26));
  animation: radarSweep 4s linear infinite;
  pointer-events: none;
  clip-path: polygon(0 100%, 0 0, 100% 100%);
}

@keyframes radarSweep {
  to { transform: rotate(360deg); }
}

.radar-legend {
  position: absolute;
  left: 50%;
  bottom: -4px;
  display: flex;
  gap: 10px;
  transform: translateX(-50%);
  white-space: nowrap;
  font-size: 6px;
  letter-spacing: 0.07em;
  color: var(--muted-2);
}

.radar-legend span {
  display: flex;
  align-items: center;
  gap: 3px;
}

.dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--muted);
}

.dot.kaiju { background: var(--orange); }
.dot.flyer { background: var(--cyan); }
.dot.you { background: var(--paper); }

/* kill feed */
.kill-feed {
  position: absolute;
  right: calc(24px + var(--safe-right));
  top: 50%;
  width: 230px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
  transform: translateY(-50%);
}

.feed-item {
  padding: 6px 9px;
  background: linear-gradient(270deg, rgba(7, 12, 17, 0.82), transparent);
  border-right: 1px solid var(--orange);
  font-size: 8px;
  letter-spacing: 0.08em;
  color: #bbc6ce;
  animation: feedIn 0.28s ease both;
  white-space: nowrap;
}

.feed-item b {
  color: var(--orange);
  font-weight: 400;
}

.feed-item.out {
  animation: feedOut 0.6s ease forwards;
}

@keyframes feedIn {
  from { opacity: 0; transform: translateX(12px); }
}

@keyframes feedOut {
  to { opacity: 0; transform: translateX(12px); }
}

/* wave banner */
.wave-banner {
  position: absolute;
  left: 50%;
  top: 31%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  transform: translate(-50%, -50%) scale(0.97);
  opacity: 0;
  pointer-events: none;
  white-space: nowrap;
}

.wave-banner.show {
  animation: bannerIn 3.2s ease both;
}

@keyframes bannerIn {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(1.05); filter: blur(4px); }
  12% { opacity: 1; transform: translate(-50%, -50%) scale(1); filter: blur(0); }
  78% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -55%) scale(1); }
}

.banner-kicker {
  padding: 4px 8px;
  font-size: 8px;
  letter-spacing: 0.18em;
  color: #100b08;
  background: var(--orange);
}

.wave-banner b {
  font-family: var(--display);
  font-size: clamp(32px, 4.5vw, 58px);
  font-weight: 700;
  line-height: 0.9;
  letter-spacing: 0.04em;
  text-shadow: 0 3px 28px rgba(0, 0, 0, 0.8);
}

.banner-sub {
  font-size: 8px;
  letter-spacing: 0.16em;
  color: #b0bcc5;
}

/* warning */
.warning-banner {
  position: absolute;
  left: 50%;
  top: calc(70px + var(--safe-top));
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 5px 12px;
  opacity: 0;
  transform: translate(-50%, -5px);
  background: rgba(30, 5, 9, 0.8);
  border: 1px solid rgba(255, 48, 76, 0.5);
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.warning-banner.show {
  opacity: 1;
  transform: translate(-50%, 0);
  animation: warningPulse 0.55s ease-in-out infinite alternate;
}

.warning-banner span {
  color: var(--red);
  font-size: 12px;
}

.warning-banner b {
  font-size: 8px;
  letter-spacing: 0.14em;
  color: #ffb4bf;
  font-weight: 400;
}

@keyframes warningPulse {
  to { border-color: rgba(255, 48, 76, 0.95); box-shadow: 0 0 18px rgba(255, 48, 76, 0.15); }
}

/* combo */
.combo {
  position: absolute;
  right: calc(24px + var(--safe-right));
  bottom: calc(290px + var(--safe-bottom));
  display: flex;
  align-items: center;
  gap: 8px;
  opacity: 0;
  transform: translateX(10px);
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.combo.active {
  opacity: 1;
  transform: translateX(0);
}

.combo span {
  font-size: 7px;
  letter-spacing: 0.12em;
  color: var(--muted);
}

.combo b {
  font-family: var(--display);
  font-size: 20px;
  color: var(--orange);
}

.combo i {
  width: 44px;
  height: 2px;
  background: rgba(255, 255, 255, 0.12);
}

.combo i em {
  display: block;
  height: 100%;
  width: 0;
  background: var(--orange);
}

/* hud footer */
.hud-footer {
  position: absolute;
  left: 50%;
  bottom: calc(9px + var(--safe-bottom));
  display: flex;
  gap: 16px;
  transform: translateX(-50%);
  font-size: 7px;
  letter-spacing: 0.08em;
  color: var(--muted-2);
  white-space: nowrap;
}

.hud-footer kbd {
  min-width: 15px;
  height: 14px;
  font-size: 6px;
}

.hud-warning {
  display: none;
  color: var(--orange);
  animation: blinkSquare 0.7s steps(2) infinite;
}

.hud-warning.show {
  display: inline;
}

/* touch */
.touch-ui {
  display: none;
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.joystick-zone {
  position: absolute;
  left: calc(22px + var(--safe-left));
  bottom: calc(26px + var(--safe-bottom));
  width: 132px;
  height: 132px;
  pointer-events: auto;
  touch-action: none;
}

.joystick-ring {
  width: 112px;
  height: 112px;
  margin: 0 auto;
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.04), rgba(0, 0, 0, 0.16));
  position: relative;
}

.joystick-ring::before,
.joystick-ring::after {
  content: "";
  position: absolute;
  background: rgba(255, 255, 255, 0.1);
}

.joystick-ring::before { left: 50%; top: 9px; width: 1px; height: 92px; }
.joystick-ring::after { top: 50%; left: 9px; height: 1px; width: 92px; }

.joystick-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 44px;
  height: 44px;
  margin: -22px 0 0 -22px;
  border-radius: 50%;
  border: 1px solid rgba(255, 90, 45, 0.8);
  background: rgba(255, 90, 45, 0.15);
  box-shadow: 0 0 20px rgba(255, 90, 45, 0.1);
  transition: transform 0.05s linear;
}

.joystick-zone > span {
  display: block;
  margin-top: 6px;
  text-align: center;
  font-size: 7px;
  letter-spacing: 0.13em;
  color: var(--muted);
}

.touch-actions {
  position: absolute;
  right: calc(19px + var(--safe-right));
  bottom: calc(22px + var(--safe-bottom));
  width: 207px;
  height: 145px;
  pointer-events: none;
}

.touch-btn {
  position: absolute;
  pointer-events: auto;
  touch-action: none;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  border: 1px solid rgba(255, 255, 255, 0.24);
  background: rgba(5, 10, 15, 0.42);
  color: var(--paper);
  font-size: 11px;
  letter-spacing: 0.12em;
  backdrop-filter: blur(4px);
}

.touch-btn small {
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.06em;
  color: var(--muted);
}

.touch-btn:active {
  background: rgba(255, 90, 45, 0.25);
  border-color: var(--orange);
}

.fire-btn {
  right: 0;
  bottom: 0;
  width: 88px;
  height: 88px;
  border-radius: 50%;
  border-color: rgba(255, 90, 45, 0.7);
  color: var(--orange-hot);
  font-size: 14px;
  font-weight: 600;
}

.missile-btn {
  right: 81px;
  bottom: 58px;
  width: 62px;
  height: 62px;
  border-radius: 50%;
  border-color: rgba(94, 231, 255, 0.55);
  color: var(--cyan);
  font-size: 10px;
}

.alt-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  font-size: 8px;
  left: 10px;
  bottom: 70px;
}

.alt-btn#touch-down {
  left: 10px;
  bottom: 8px;
}

.look-hint {
  position: absolute;
  left: 50%;
  top: 56%;
  transform: translateX(-50%);
  font-size: 7px;
  letter-spacing: 0.17em;
  color: rgba(255, 255, 255, 0.38);
  opacity: 0;
  transition: opacity 0.5s ease;
}

.look-hint.show {
  opacity: 1;
}

/* ═══════════════════ UPGRADE ═══════════════════ */
#upgrade {
  z-index: 45;
}

.upgrade-backdrop {
  background:
    radial-gradient(ellipse at 50% 35%, rgba(255, 90, 45, 0.09), transparent 45%),
    rgba(2, 4, 6, 0.86);
}

.upgrade-shell {
  position: relative;
  width: min(1130px, 94vw);
  max-height: 93vh;
  overflow: auto;
  padding: clamp(22px, 3.4vw, 42px);
  background: linear-gradient(140deg, rgba(12, 18, 25, 0.98), rgba(5, 9, 13, 0.98));
  border: 1px solid var(--line);
  box-shadow: 0 40px 120px rgba(0, 0, 0, 0.75);
  clip-path: polygon(0 0, calc(100% - 26px) 0, 100% 26px, 100% 100%, 26px 100%, 0 calc(100% - 26px));
}

.upgrade-shell::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  width: 240px;
  height: 2px;
  background: linear-gradient(90deg, var(--orange), transparent);
}

.upgrade-header {
  display: flex;
  justify-content: space-between;
  gap: 30px;
  align-items: flex-start;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--line-soft);
}

.upgrade-header h2 {
  margin-top: 8px;
  font-size: clamp(36px, 4.4vw, 57px);
  line-height: 0.9;
  letter-spacing: -0.01em;
}

.upgrade-header h2 span {
  color: var(--orange);
}

.upgrade-header p {
  margin-top: 8px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.04em;
  color: var(--muted);
}

.upgrade-wave {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  flex-shrink: 0;
}

.upgrade-wave span,
.upgrade-wave small {
  font-size: 7px;
  letter-spacing: 0.13em;
  color: var(--muted);
}

.upgrade-wave b {
  font-family: var(--display);
  font-size: 48px;
  line-height: 0.9;
  color: var(--orange);
}

.upgrade-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  margin: 16px 0 20px;
  background: var(--line-soft);
  border: 1px solid var(--line-soft);
}

.upgrade-stats div {
  padding: 10px 13px;
  background: #080d12;
}

.upgrade-stats span {
  display: block;
  font-size: 7px;
  letter-spacing: 0.12em;
  color: var(--muted-2);
}

.upgrade-stats b {
  display: block;
  margin-top: 3px;
  font-family: var(--display);
  font-size: 20px;
  font-weight: 500;
  color: var(--paper);
}

.upgrade-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 11px;
}

.upgrade-card {
  position: relative;
  display: flex;
  flex-direction: column;
  min-height: 245px;
  padding: 17px;
  text-align: left;
  overflow: hidden;
  background:
    linear-gradient(155deg, rgba(255, 255, 255, 0.045), transparent 44%),
    #080d12;
  border: 1px solid var(--line-soft);
  clip-path: polygon(0 0, calc(100% - 14px) 0, 100% 14px, 100% 100%, 0 100%);
  transition: border-color 0.2s ease, background 0.2s ease, transform 0.2s ease;
}

.upgrade-card::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(115deg, transparent 44%, rgba(255, 255, 255, 0.04) 45%, transparent 46%);
  opacity: 0;
  transition: opacity 0.25s ease;
}

.upgrade-card:hover:not(.taken) {
  transform: translateY(-3px);
  border-color: rgba(255, 255, 255, 0.3);
  background:
    linear-gradient(155deg, rgba(255, 90, 45, 0.09), transparent 50%),
    #0a1017;
}

.upgrade-card:hover::after {
  opacity: 1;
}

.upgrade-card.selected {
  border-color: var(--orange);
  background:
    linear-gradient(155deg, rgba(255, 90, 45, 0.15), transparent 55%),
    #0b1016;
  box-shadow: inset 0 0 34px rgba(255, 90, 45, 0.06);
}

.upgrade-card.taken {
  opacity: 0.35;
  cursor: default;
}

.upgrade-card-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.upgrade-cat {
  padding: 3px 6px;
  font-size: 6px;
  letter-spacing: 0.12em;
  color: var(--cyan);
  border: 1px solid rgba(94, 231, 255, 0.25);
}

.upgrade-card[data-cat="WEAPON"] .upgrade-cat {
  color: var(--orange);
  border-color: rgba(255, 90, 45, 0.3);
}

.upgrade-index {
  font-size: 8px;
  color: var(--muted-2);
}

.upgrade-icon {
  position: relative;
  display: grid;
  place-items: center;
  width: 58px;
  height: 58px;
  margin: 20px 0 16px;
  border: 1px solid rgba(255, 255, 255, 0.13);
  transform: skewX(-8deg);
  font-family: var(--display);
  font-size: 26px;
  color: var(--orange);
  background: rgba(255, 255, 255, 0.02);
}

.upgrade-icon::before,
.upgrade-icon::after {
  content: "";
  position: absolute;
  background: rgba(255, 90, 45, 0.55);
}

.upgrade-icon::before { width: 9px; height: 1px; left: -4px; top: -1px; }
.upgrade-icon::after { width: 1px; height: 9px; right: -1px; bottom: -4px; }

.upgrade-name {
  font-family: var(--display);
  font-size: 24px;
  font-weight: 600;
  line-height: 0.95;
  letter-spacing: 0.03em;
}

.upgrade-desc {
  margin-top: 8px;
  font-family: var(--mono);
  font-size: 8.5px;
  line-height: 1.6;
  color: var(--muted);
}

.upgrade-delta {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: auto;
  padding-top: 16px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.04em;
  color: var(--green);
}

.upgrade-delta::before {
  content: "";
  width: 13px;
  height: 1px;
  background: currentColor;
}

.upgrade-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  margin-top: 22px;
  padding-top: 17px;
  border-top: 1px solid var(--line-soft);
}

.upgrade-tip {
  font-size: 8px;
  letter-spacing: 0.12em;
  color: var(--muted-2);
}

.upgrade-footer .btn {
  min-height: 49px;
  min-width: 235px;
  font-size: 11px;
}

/* ═══════════════════ PAUSE / GAME OVER ═══════════════════ */
#pause,
#gameover {
  z-index: 50;
}

.pause-card {
  width: min(540px, 94vw);
  text-align: center;
}

.pause-card::before,
.gameover-card::before {
  left: 50%;
  transform: translateX(-50%);
}

.pause-card .panel-kicker {
  justify-content: center;
}

.pause-card h2 {
  font-size: clamp(58px, 9vw, 95px);
  color: var(--paper);
}

.pause-card p {
  margin-top: 9px;
  font-family: var(--mono);
  font-size: 9px;
  line-height: 1.6;
  color: var(--muted);
}

.pause-actions {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 28px;
}

.pause-controls {
  margin-top: 26px;
  padding-top: 17px;
  border-top: 1px solid var(--line-soft);
  font-family: var(--mono);
  font-size: 7px;
  line-height: 2.3;
  letter-spacing: 0.08em;
  color: var(--muted-2);
}

.pause-controls kbd {
  margin: 0 1px;
}

.pause-controls span {
  margin: 0 7px;
  color: var(--orange);
}

.gameover-backdrop {
  background:
    radial-gradient(ellipse at 50% 42%, rgba(160, 10, 26, 0.18), transparent 45%),
    rgba(2, 3, 5, 0.9);
}

.gameover-card {
  width: min(760px, 94vw);
  text-align: center;
}

.gameover-card::before {
  background: var(--red);
}

.gameover-card .panel-kicker {
  justify-content: center;
  color: var(--red);
}

.gameover-card h2 {
  margin-top: 14px;
  font-size: clamp(58px, 8vw, 105px);
  color: var(--paper);
}

.gameover-card h2 span {
  color: var(--red);
  -webkit-text-stroke: 1px rgba(255, 48, 76, 0.6);
  color: transparent;
}

.gameover-card > p {
  max-width: 440px;
  margin: 10px auto 0;
  font-family: var(--mono);
  font-size: 9px;
  line-height: 1.65;
  color: var(--muted);
}

.gameover-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  margin-top: 25px;
  background: var(--line-soft);
  border: 1px solid var(--line-soft);
}

.gameover-stats div {
  padding: 13px 8px;
  background: #080c11;
}

.gameover-stats span {
  display: block;
  font-size: 6px;
  letter-spacing: 0.1em;
  color: var(--muted-2);
}

.gameover-stats b {
  display: block;
  margin-top: 4px;
  font-family: var(--display);
  font-size: 25px;
  font-weight: 500;
}

.gameover-best {
  min-height: 18px;
  margin-top: 15px;
  font-size: 8px;
  letter-spacing: 0.15em;
  color: var(--orange);
}

.gameover-actions {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 20px;
}

.gameover-actions .btn {
  min-height: 50px;
}

/* ═══════════════════ RESPONSIVE ═══════════════════ */
@media (max-width: 1050px) {
  .menu-layout {
    grid-template-columns: minmax(0, 1.6fr) minmax(235px, 0.6fr);
    gap: 35px;
  }
  .logo {
    font-size: clamp(68px, 11.2vw, 132px);
  }
  .deck {
    max-width: 430px;
  }
  .control-strip {
    gap: 12px;
  }
  .control-strip div:nth-child(5) {
    display: none;
  }
}

@media (max-width: 860px) {
  .menu-screen {
    padding-left: 25px;
    padding-right: 25px;
  }
  .menu-layout {
    grid-template-columns: 1fr;
  }
  .menu-side {
    display: none;
  }
  .menu-copy {
    max-width: 660px;
  }
  .menu-meta {
    display: none;
  }
  .hud-top {
    grid-template-columns: 1fr auto;
  }
  .city-status {
    position: absolute;
    left: 50%;
    top: 0;
