import * as THREE from "three";

const _v = new THREE.Vector3();
const _v2 = new THREE.Vector3();
const _q = new THREE.Quaternion();
const _m = new THREE.Matrix4();
const _s = new THREE.Vector3();
const _up = new THREE.Vector3(0, 0, 1);

function makeParticleTexture() {
  const c = document.createElement("canvas");
  c.width = c.height = 64;
  const ctx = c.getContext("2d");
  const g = ctx.createRadialGradient(32, 32, 0, 32, 32, 31);
  g.addColorStop(0, "rgba(255,255,255,1)");
  g.addColorStop(0.28, "rgba(255,255,255,0.82)");
  g.addColorStop(0.62, "rgba(255,255,255,0.18)");
  g.addColorStop(1, "rgba(255,255,255,0)");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 64, 64);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

class ParticleSystem {
  constructor(scene, { capacity = 900, blending = THREE.AdditiveBlending, texture }) {
    this.capacity = capacity;
    this.particles = [];
    this.geometry = new THREE.BufferGeometry();
    this.positions = new Float32Array(capacity * 3);
    this.colors = new Float32Array(capacity * 3);
    this.sizes = new Float32Array(capacity);
    this.alphas = new Float32Array(capacity);
    this.geometry.setAttribute("position", new THREE.BufferAttribute(this.positions, 3).setUsage(THREE.DynamicDrawUsage));
    this.geometry.setAttribute("aColor", new THREE.BufferAttribute(this.colors, 3).setUsage(THREE.DynamicDrawUsage));
    this.geometry.setAttribute("aSize", new THREE.BufferAttribute(this.sizes, 1).setUsage(THREE.DynamicDrawUsage));
    this.geometry.setAttribute("aAlpha", new THREE.BufferAttribute(this.alphas, 1).setUsage(THREE.DynamicDrawUsage));
    this.geometry.setDrawRange(0, 0);
    this.material = new THREE.ShaderMaterial({
      uniforms: {
        uMap: { value: texture },
        uScale: { value: 900 },
      },
      vertexShader: /* glsl */ `
        attribute vec3 aColor;
        attribute float aSize;
        attribute float aAlpha;
        uniform float uScale;
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_Position = projectionMatrix * mv;
          gl_PointSize = clamp(aSize * uScale / max(1.0, -mv.z), 1.0, 110.0);
          vColor = aColor;
          vAlpha = aAlpha;
        }
      `,
      fragmentShader: /* glsl */ `
        uniform sampler2D uMap;
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          vec4 tex = texture2D(uMap, gl_PointCoord);
          float a = tex.a * vAlpha;
          if (a < 0.008) discard;
          gl_FragColor = vec4(vColor, a);
        }
      `,
      transparent: true,
      depthWrite: false,
      blending,
    });
    this.points = new THREE.Points(this.geometry, this.material);
    this.points.frustumCulled = false;
    this.points.renderOrder = 6;
    scene.add(this.points);
  }

  add(p) {
    if (this.particles.length >= this.capacity) {
      // recycle the oldest particle
      this.particles.shift();
    }
    this.particles.push(p);
  }

  update(dt, camera) {
    let n = 0;
    for (let i = 0; i < this.particles.length; i++) {
      const p = this.particles[i];
      p.life -= dt;
      if (p.life <= 0) continue;

      p.vel.y -= (p.gravity || 0) * dt;
      const drag = Math.exp(-(p.drag || 0) * dt);
      p.vel.multiplyScalar(drag);
      p.pos.addScaledVector(p.vel, dt);

      p.size += (p.grow || 0) * dt;
      const t = p.life / p.maxLife;
      const alpha = p.fade === "in" ? (1 - t) * p.alpha : t * p.alpha;

      this.positions[n * 3] = p.pos.x;
      this.positions[n * 3 + 1] = p.pos.y;
      this.positions[n * 3 + 2] = p.pos.z;
      this.colors[n * 3] = p.color.r;
      this.colors[n * 3 + 1] = p.color.g;
      this.colors[n * 3 + 2] = p.color.b;
      this.sizes[n] = Math.max(0.01, p.size);
      this.alphas[n] = Math.max(0, alpha);
      n++;
    }
    this.particles.length = n;
    this.geometry.setDrawRange(0, n);
    this.geometry.attributes.position.needsUpdate = true;
    this.geometry.attributes.aColor.needsUpdate = true;
    this.geometry.attributes.aSize.needsUpdate = true;
    this.geometry.attributes.aAlpha.needsUpdate = true;
  }
}

export class Effects {
  constructor(scene, camera) {
    this.scene = scene;
    this.camera = camera;
    this.texture = makeParticleTexture();
    this.sparks = new ParticleSystem(scene, {
      capacity: 1400,
      blending: THREE.AdditiveBlending,
      texture: this.texture,
    });
    this.smoke = new ParticleSystem(scene, {
      capacity: 650,
      blending: THREE.NormalBlending,
      texture: this.texture,
    });

    this.tracers = [];
    this.tracerGeo = new THREE.BoxGeometry(1, 1, 1);
    for (let i = 0; i < 46; i++) {
      const mat = new THREE.MeshBasicMaterial({
        color: 0xffddaa,
        transparent: true,
        opacity: 0,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      });
      const mesh = new THREE.Mesh(this.tracerGeo, mat);
      mesh.visible = false;
      mesh.frustumCulled = false;
      mesh.renderOrder = 7;
      scene.add(mesh);
      this.tracers.push({ mesh, life: 0, maxLife: 0.2 });
    }

    this.flashes = [];
    for (let i = 0; i < 14; i++) {
      const mat = new THREE.SpriteMaterial({
        map: this.texture,
        color: 0xffb060,
        transparent: true,
        opacity: 0,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      });
      const sprite = new THREE.Sprite(mat);
      sprite.visible = false;
      sprite.renderOrder = 8;
      scene.add(sprite);
      this.flashes.push({ sprite, life: 0, maxLife: 0.3, target: 10 });
    }

    this.rings = [];
    const ringGeo = new THREE.RingGeometry(0.72, 1, 48);
    for (let i = 0; i < 10; i++) {
      const mat = new THREE.MeshBasicMaterial({
        color: 0xff8a46,
        transparent: true,
        opacity: 0,
        side: THREE.DoubleSide,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      });
      const ring = new THREE.Mesh(ringGeo, mat);
      ring.visible = false;
      ring.renderOrder = 7;
      scene.add(ring);
      this.rings.push({ mesh: ring, life: 0, maxLife: 0.5, target: 16 });
    }

    this.debris = [];
    this.debrisMesh = new THREE.InstancedMesh(
      new THREE.BoxGeometry(1, 1, 1),
      new THREE.MeshStandardMaterial({ color: 0x20262b, roughness: 0.92, metalness: 0.08 }),
      190
    );
    this.debrisMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.debrisMesh.frustumCulled = false;
    this.debrisMesh.castShadow = false;
    scene.add(this.debrisMesh);
    for (let i = 0; i < 190; i++) {
      this.debris.push(null);
      this._hideDebris(i);
    }

    this.debrisCursor = 0;
    this._tracerCursor = 0;
    this._flashCursor = 0;
    this._ringCursor = 0;
    this._debrisActive = false;
  }

  _hideDebris(i) {
    _s.set(0.0001, 0.0001, 0.0001);
    _v.set(0, -500, 0);
    _q.identity();
    _m.compose(_v, _q, _s);
    this.debrisMesh.setMatrixAt(i, _m);
    if (i === 0) this.debrisMesh.instanceMatrix.needsUpdate = true;
  }

  setScale(height) {
    const s = Math.min(2.2, Math.max(0.8, height / 900));
    this.sparks.material.uniforms.uScale.value = 900 * s;
    this.smoke.material.uniforms.uScale.value = 900 * s;
  }

  spark(pos, count, opts = {}) {
    const {
      speed = 18,
      spread = 1,
      color = new THREE.Color("#ff9a4f"),
      life = 0.65,
      size = 0.55,
      gravity = 18,
      drag = 1.2,
      directional = null,
    } = opts;
    for (let i = 0; i < count; i++) {
      const c = color.clone();
      if (Math.random() < 0.35) c.lerp(new THREE.Color("#fff3cb"), 0.7);
      const vel = new THREE.Vector3(
        (Math.random() - 0.5) * 2,
        (Math.random() - 0.5) * 2,
        (Math.random() - 0.5) * 2
      ).normalize();
      if (directional) vel.lerp(directional, 0.45).normalize();
      vel.multiplyScalar(speed * (0.3 + Math.random() * 0.85) * spread);
      this.sparks.add({
        pos: pos.clone(),
        vel,
        life: life * (0.5 + Math.random() * 0.8),
        maxLife: life,
        size: size * (0.5 + Math.random() * 0.85),
        color: c,
        alpha: 0.92,
        gravity,
        drag,
        grow: -0.15,
      });
    }
  }

  smokePuff(pos, count = 10, opts = {}) {
    const {
      speed = 4,
      life = 2.8,
      size = 1.9,
      color = new THREE.Color("#57616a"),
      alpha = 0.32,
      gravity = -0.6,
      rise = 0,
    } = opts;
    for (let i = 0; i < count; i++) {
      const c = color.clone().offsetHSL(0, 0, (Math.random() - 0.5) * 0.08);
      const vel = new THREE.Vector3(
        (Math.random() - 0.5) * 2,
        rise + Math.random() * 1.6,
        (Math.random() - 0.5) * 2
      ).multiplyScalar(speed * (0.4 + Math.random() * 0.7));
      this.smoke.add({
        pos: pos.clone().add(new THREE.Vector3((Math.random() - 0.5) * 2, Math.random() * 1.5, (Math.random() - 0.5) * 2)),
        vel,
        life: life * (0.65 + Math.random() * 0.65),
        maxLife: life,
        size: size * (0.65 + Math.random() * 0.9),
        color: c,
        alpha,
        gravity,
        drag: 0.7,
        grow: 1.9,
        fade: "out",
      });
    }
  }

  explosion(pos, scale = 1, color = 0xff7a3c) {
    const c = new THREE.Color(color);
    this.spark(pos, Math.round(30 + 28 * scale), {
      speed: 24 * scale,
      color: c,
      life: 0.85,
      size: 0.9 * scale,
      gravity: 17,
      drag: 1.5,
    });
    this.spark(pos, Math.round(10 + 10 * scale), {
      speed: 50 * scale,
      color: new THREE.Color("#ffe6ad"),
      life: 0.4,
      size: 0.42,
      gravity: 4,
      drag: 0.4,
    });
    this.smokePuff(pos, Math.round(12 + 8 * scale), {
      speed: 4.5 * scale,
      life: 2.6,
      size: 2.2 * scale,
      color: new THREE.Color("#3a4148"),
      alpha: 0.42,
      gravity: -0.3,
      rise: 1.0,
    });
    this.flashAt(pos, c, 20 * scale, 0.38);
    this.ringAt(pos, c, 16 * scale, 0.5);
  }

  hit(pos, color = 0xffb066, crit = false) {
    this.spark(pos, crit ? 16 : 9, {
      speed: crit ? 20 : 12,
      color: new THREE.Color(color),
      life: 0.42,
      size: 0.35,
      gravity: 10,
      drag: 1.3,
    });
    this.flashAt(pos, new THREE.Color(color), 3.8, 0.14);
  }

  buildingCollapse(pos, height = 30) {
    const center = pos.clone();
    center.y = Math.min(height * 0.45, 18);
    this.smokePuff(center, 30, {
      speed: 7,
      life: 4.2,
      size: 3.4,
      color: new THREE.Color("#4b4d4d"),
      alpha: 0.48,
      gravity: -0.7,
      rise: 2.2,
    });
    this.spark(center, 45, {
      speed: 20,
      color: new THREE.Color("#ff8f45"),
      life: 1.2,
      size: 0.8,
      gravity: 12,
      drag: 1.1,
    });
    this.debrisBurst(center, 32, 1.5);
    this.flashAt(center, new THREE.Color("#ff8b48"), 30, 0.6);
    this.ringAt(center, new THREE.Color("#ff7b3a"), 32, 0.9);
  }

  muzzle(pos, direction, color = 0xffd08a) {
    this.flashAt(pos, new THREE.Color(color), 2.4, 0.06);
    this.spark(pos, 3, {
      speed: 8,
      color: new THREE.Color(color),
      life: 0.12,
      size: 0.2,
      gravity: 0,
      drag: 0,
      directional: direction,
    });
  }

  tracer(from, to, color = 0xffd293) {
    const t = this.tracers[this._tracerCursor];
    this._tracerCursor = (this._tracerCursor + 1) % this.tracers.length;
    _v.subVectors(to, from);
    const len = _v.length();
    if (len < 0.01) return;
    _v.multiplyScalar(1 / len);
    t.mesh.position.copy(from).addScaledVector(_v, len / 2);
    t.mesh.quaternion.setFromUnitVectors(_up, _v);
    t.mesh.scale.set(0.045, 0.045, len);
    t.mesh.material.color.set(color);
    t.mesh.material.opacity = 0.95;
    t.mesh.visible = true;
    t.life = 0.14;
    t.maxLife = 0.14;
  }

  missileTrail(pos) {
    if (Math.random() < 0.75) {
      this.smokePuff(pos, 1, {
        speed: 1.2,
        life: 1.1,
        size: 0.45,
        color: new THREE.Color("#7f858a"),
        alpha: 0.26,
        gravity: -0.1,
        rise: 0.2,
      });
    }
    this.spark(pos, 1, {
      speed: 5,
      color: new THREE.Color("#ffc16d"),
      life: 0.22,
      size: 0.32,
      gravity: 0,
      drag: 2,
    });
  }

  flashAt(pos, color, size = 8, life = 0.2) {
    const f = this.flashes[this._flashCursor];
    this._flashCursor = (this._flashCursor + 1) % this.flashes.length;
    f.sprite.position.copy(pos);
    f.sprite.material.color.copy(color);
    f.sprite.material.opacity = 1;
    f.sprite.scale.setScalar(0.1);
    f.sprite.visible = true;
    f.life = life;
    f.maxLife = life;
    f.target = size;
  }

  ringAt(pos, color, size = 12, life = 0.4) {
    const r = this.rings[this._ringCursor];
    this._ringCursor = (this._ringCursor + 1) % this.rings.length;
    r.mesh.position.copy(pos);
    r.mesh.material.color.copy(color);
    r.mesh.material.opacity = 0.8;
    r.mesh.scale.setScalar(0.4);
    r.mesh.visible = true;
    r.mesh.quaternion.copy(this.camera.quaternion);
    r.life = life;
    r.maxLife = life;
    r.target = size;
  }

  debrisBurst(pos, count = 24, scale = 1) {
    for (let i = 0; i < count; i++) {
      const index = this.debrisCursor;
      this.debrisCursor = (this.debrisCursor + 1) % this.debris.length;
      let d = this.debris[index];
      if (!d) {
        d = {
          pos: new THREE.Vector3(),
          vel: new THREE.Vector3(),
          rot: new THREE.Euler(),
          spin: new THREE.Vector3(),
          scale: new THREE.Vector3(),
          life: 0,
          maxLife: 0,
        };
        this.debris[index] = d;
      }
      d.pos.copy(pos).add(
        new THREE.Vector3((Math.random() - 0.5) * 4, (Math.random() - 0.4) * 3, (Math.random() - 0.5) * 4)
      );
      d.vel.set(
        (Math.random() - 0.5) * 18,
        6 + Math.random() * 15,
        (Math.random() - 0.5) * 18
      );
      d.rot.set(Math.random() * 6, Math.random() * 6, Math.random() * 6);
      d.spin.set((Math.random() - 0.5) * 7, (Math.random() - 0.5) * 7, (Math.random() - 0.5) * 7);
      const s = (0.5 + Math.random() * 2.6) * scale;
      d.scale.set(s, s * (0.35 + Math.random() * 1.5), s);
      d.life = 2.3 + Math.random() * 2.2;
      d.maxLife = d.life;
      this.debrisMesh.setColorAt(index, new THREE.Color().setHSL(0.09, 0.03, 0.09 + Math.random() * 0.13));
    }
    if (this.debrisMesh.instanceColor) this.debrisMesh.instanceColor.needsUpdate = true;
    this._debrisActive = true;
  }

  update(dt, time) {
    this.sparks.update(dt, this.camera);
    this.smoke.update(dt, this.camera);

    for (const t of this.tracers) {
      if (t.life <= 0) continue;
      t.life -= dt;
      const f = Math.max(0, t.life / t.maxLife);
      t.mesh.material.opacity = f * 0.95;
      if (t.life <= 0) t.mesh.visible = false;
    }

    for (const f of this.flashes) {
      if (f.life <= 0) continue;
      f.life -= dt;
      const t = 1 - Math.max(0, f.life / f.maxLife);
      f.sprite.scale.setScalar(0.1 + f.target * Math.min(1, t * 1.8));
      f.sprite.material.opacity = Math.max(0, 1 - t) * (1 - t);
      if (f.life <= 0) f.sprite.visible = false;
    }

    for (const r of this.rings) {
      if (r.life <= 0) continue;
      r.life -= dt;
      const t = 1 - Math.max(0, r.life / r.maxLife);
      r.mesh.scale.setScalar(0.4 + r.target * Math.sqrt(t));
      r.mesh.material.opacity = Math.max(0, 1 - t) * 0.88;
      r.mesh.quaternion.copy(this.camera.quaternion);
      if (r.life <= 0) r.mesh.visible = false;
    }

    if (this._debrisActive) {
      let any = false;
      for (let i = 0; i < this.debris.length; i++) {
        const d = this.debris[i];
        if (!d || d.life <= 0) {
          if (d && d.life > -1) {
            this._hideDebris(i);
            d.life = -2;
          }
          continue;
        }
        any = true;
        d.life -= dt;
        d.vel.y -= 24 * dt;
        d.pos.addScaledVector(d.vel, dt);
        if (d.pos.y < 1.2) {
          d.pos.y = 1.2;
          d.vel.y *= -0.22;
          d.vel.x *= 0.72;
          d.vel.z *= 0.72;
          d.spin.multiplyScalar(0.7);
        }
        d.rot.x += d.spin.x * dt;
        d.rot.y += d.spin.y * dt;
        d.rot.z += d.spin.z * dt;
        _q.setFromEuler(d.rot);
        const fade = Math.min(1, d.life / 0.4);
        _s.copy(d.scale).multiplyScalar(fade);
        _m.compose(d.pos, _q, _s);
        this.debrisMesh.setMatrixAt(i, _m);
        if (d.life <= 0) {
          d.life = -2;
          this._hideDebris(i);
        }
      }
      this.debrisMesh.instanceMatrix.needsUpdate = true;
      if (!any) this._debrisActive = false;
    }
  }
}

export class SoundEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.engine = null;
    this.muted = false;
    this.started = false;
    this.lastShot = 0;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === "suspended") this.ctx.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.5;
    const comp = this.ctx.createDynamicsCompressor();
    comp.threshold.value = -16;
    comp.knee.value = 18;
    comp.ratio.value = 5;
    comp.attack.value = 0.003;
    comp.release.value = 0.22;
    this.master.connect(comp);
    comp.connect(this.ctx.destination);

    this.noiseBuffer = this._makeNoise(2.2);
    this._startEngine();
    this._startAmbience();
    this.started = true;
  }

  _makeNoise(seconds) {
    const len = Math.floor(this.ctx.sampleRate * seconds);
    const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < len; i++) {
      data[i] = Math.random() * 2 - 1;
    }
    return buffer;
  }

  _noiseSource(duration = 0.2) {
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;
    const offset = Math.random() * Math.max(0, this.noiseBuffer.duration - duration - 0.05);
    src.start(this.ctx.currentTime, offset, duration + 0.03);
    return src;
  }

  _startEngine() {
    const ctx = this.ctx;
    const engineGain = ctx.createGain();
    engineGain.gain.value = 0.016;
    engineGain.connect(this.master);

    const low = ctx.createOscillator();
    low.type = "sawtooth";
    low.frequency.value = 48;
    const lowFilter = ctx.createBiquadFilter();
    lowFilter.type = "lowpass";
    lowFilter.frequency.value = 240;
    lowFilter.Q.value = 4;
    low.connect(lowFilter);
    lowFilter.connect(engineGain);

    const high = ctx.createOscillator();
    high.type = "triangle";
    high.frequency.value = 96;
    const highGain = ctx.createGain();
    highGain.gain.value = 0.26;
    high.connect(highGain);
    highGain.connect(engineGain);

    const lfo = ctx.createOscillator();
    lfo.type = "sine";
    lfo.frequency.value = 11.2;
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = 0.0065;
    lfo.connect(lfoGain);
    lfoGain.connect(engineGain.gain);

    const turbine = ctx.createOscillator();
    turbine.type = "sine";
    turbine.frequency.value = 630;
    const turbineGain = ctx.createGain();
    turbineGain.gain.value = 0.0032;
    turbine.connect(turbineGain);
    turbineGain.connect(this.master);

    const windSrc = this._noiseSource(2);
    const windFilter = ctx.createBiquadFilter();
    windFilter.type = "lowpass";
    windFilter.frequency.value = 480;
    windFilter.Q.value = 0.3;
    const windGain = ctx.createGain();
    windGain.gain.value = 0.018;
    windSrc.connect(windFilter);
    windFilter.connect(windGain);
    windGain.connect(this.master);

    low.start();
    high.start();
    lfo.start();
    turbine.start();

    this.engine = {
      gain: engineGain,
      low,
      high,
      turbine,
      wind: windGain,
      windFilter,
    };
  }

  _startAmbience() {
    const ctx = this.ctx;
    const pad = ctx.createGain();
    pad.gain.value = 0.011;
    pad.connect(this.master);
    const filter = ctx.createBiquadFilter();
    filter.type = "lowpass";
    filter.frequency.value = 460;
    filter.connect(pad);
    const frequencies = [55, 82.41, 110, 164.81];
    for (let i = 0; i < frequencies.length; i++) {
      const osc = ctx.createOscillator();
      osc.type = i % 2 ? "triangle" : "sine";
      osc.frequency.value = frequencies[i];
      osc.detune.value = (i - 1.5) * 3;
      const g = ctx.createGain();
      g.gain.value = i === 0 ? 0.65 : 0.18;
      osc.connect(g);
      g.connect(filter);
      osc.start();
    }
    this.ambience = { pad, filter };
  }

  updateEngine(speed, boost, active = true) {
    if (!this.engine || !this.ctx) return;
    const t = this.ctx.currentTime;
    const target = active ? 1 : 0;
    const freq = 48 + speed * 0.9 + (boost ? 16 : 0);
    this.engine.low.frequency.setTargetAtTime(freq, t, 0.08);
    this.engine.high.frequency.setTargetAtTime(freq * 2.02, t, 0.08);
    this.engine.turbine.frequency.setTargetAtTime(560 + speed * 6 + (boost ? 160 : 0), t, 0.1);
    this.engine.gain.gain.setTargetAtTime((0.012 + speed * 0.00014) * target, t, 0.08);
    this.engine.wind.gain.setTargetAtTime((0.013 + speed * 0.00024 + (boost ? 0.017 : 0)) * target, t, 0.08);
    this.engine.windFilter.frequency.setTargetAtTime(330 + speed * 8 + (boost ? 420 : 0), t, 0.1);
  }

  setMuted(muted) {
    this.muted = muted;
    if (!this.master || !this.ctx) return;
    this.master.gain.setTargetAtTime(muted ? 0 : 0.5, this.ctx.currentTime, 0.06);
  }

  toggleMute() {
    this.setMuted(!this.muted);
    return this.muted;
  }

  gun() {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    if (t - this.lastShot < 0.018) return;
    this.lastShot = t;

    const src = this._noiseSource(0.08);
    const filter = this.ctx.createBiquadFilter();
    filter.type = "bandpass";
    filter.frequency.setValueAtTime(950 + Math.random() * 500, t);
    filter.Q.value = 0.7;
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(0.17, t);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.075);
    src.connect(filter);
    filter.connect(gain);
    gain.connect(this.master);

    const thump = this.ctx.createOscillator();
    thump.type = "square";
    thump.frequency.setValueAtTime(88, t);
    thump.frequency.exponentialRampToValueAtTime(32, t + 0.06);
    const tg = this.ctx.createGain();
    tg.gain.setValueAtTime(0.075, t);
    tg.gain.exponentialRampToValueAtTime(0.0001, t + 0.07);
    thump.connect(tg);
    tg.connect(this.master);
    thump.start(t);
    thump.stop(t + 0.08);
  }

  overheat() {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    osc.type = "square";
    osc.frequency.setValueAtTime(230, t);
    osc.frequency.setValueAtTime(170, t + 0.07);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.04, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.25);
    osc.connect(g);
    g.connect(this.master);
    osc.start(t);
    osc.stop(t + 0.26);
  }

  hit(crit = false) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    osc.type = "sine";
    osc.frequency.setValueAtTime(crit ? 1600 : 1150, t);
    osc.frequency.exponentialRampToValueAtTime(crit ? 2400 : 1650, t + 0.04);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(crit ? 0.065 : 0.033, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.08);
    osc.connect(g);
    g.connect(this.master);
    osc.start(t);
    osc.stop(t + 0.09);
  }

  missile() {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    const src = this._noiseSource(0.65);
    const f = this.ctx.createBiquadFilter();
    f.type = "bandpass";
    f.frequency.setValueAtTime(280, t);
    f.frequency.exponentialRampToValueAtTime(2200, t + 0.5);
    f.Q.value = 0.8;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.18, t + 0.06);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.62);
    src.connect(f);
    f.connect(g);
    g.connect(this.master);

    const osc = this.ctx.createOscillator();
    osc.type = "sawtooth";
    osc.frequency.setValueAtTime(150, t);
    osc.frequency.exponentialRampToValueAtTime(60, t + 0.4);
    const og = this.ctx.createGain();
    og.gain.setValueAtTime(0.045, t);
    og.gain.exponentialRampToValueAtTime(0.0001, t + 0.4);
    osc.connect(og);
    og.connect(this.master);
    osc.start(t);
    osc.stop(t + 0.42);
  }

  explosion(size = 1) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    const src = this._noiseSource(1.2);
    const f = this.ctx.createBiquadFilter();
    f.type = "lowpass";
    f.frequency.setValueAtTime(1900 * size, t);
    f.frequency.exponentialRampToValueAtTime(100, t + 0.8);
    f.Q.value = 0.6;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.31 * Math.min(1.3, size), t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 1.05);
    src.connect(f);
    f.connect(g);
    g.connect(this.master);

    const sub = this.ctx.createOscillator();
    sub.type = "sine";
    sub.frequency.setValueAtTime(75 * Math.max(0.7, size), t);
    sub.frequency.exponentialRampToValueAtTime(26, t + 0.75);
    const sg = this.ctx.createGain();
    sg.gain.setValueAtTime(0.23 * Math.min(1.4, size), t);
    sg.gain.exponentialRampToValueAtTime(0.0001, t + 0.9);
    sub.connect(sg);
    sg.connect(this.master);
    sub.start(t);
    sub.stop(t + 0.92);
  }

  enemyShot() {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    osc.type = "sawtooth";
    osc.frequency.setValueAtTime(920, t);
    osc.frequency.exponentialRampToValueAtTime(260, t + 0.22);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.034, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.24);
    osc.connect(g);
    g.connect(this.master);
    osc.start(t);
    osc.stop(t + 0.25);
  }

  playerHit() {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    const src = this._noiseSource(0.3);
    const f = this.ctx.createBiquadFilter();
    f.type = "lowpass";
    f.frequency.setValueAtTime(500, t);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.22, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.28);
    src.connect(f);
    f.connect(g);
    g.connect(this.master);

    const beep = this.ctx.createOscillator();
    beep.type = "square";
    beep.frequency.setValueAtTime(320, t);
    beep.frequency.setValueAtTime(250, t + 0.1);
    const bg = this.ctx.createGain();
    bg.gain.setValueAtTime(0.04, t);
    bg.gain.exponentialRampToValueAtTime(0.0001, t + 0.3);
    beep.connect(bg);
    bg.connect(this.master);
    beep.start(t);
    beep.stop(t + 0.31);
  }

  roar(big = false) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    const src = this._noiseSource(1.6);
    const f = this.ctx.createBiquadFilter();
    f.type = "lowpass";
    f.frequency.setValueAtTime(420, t);
    f.frequency.exponentialRampToValueAtTime(160, t + 1.2);
    f.Q.value = 2;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(big ? 0.18 : 0.1, t + 0.18);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 1.35);
    src.connect(f);
    f.connect(g);
    g.connect(this.master);

    const osc = this.ctx.createOscillator();
    osc.type = "sawtooth";
    osc.frequency.setValueAtTime(big ? 68 : 96, t);
    osc.frequency.exponentialRampToValueAtTime(big ? 32 : 48, t + 1.05);
    const og = this.ctx.createGain();
    og.gain.setValueAtTime(0.0001, t);
    og.gain.exponentialRampToValueAtTime(0.07, t + 0.2);
    og.gain.exponentialRampToValueAtTime(0.0001, t + 1.3);
    osc.connect(og);
    og.connect(this.master);
    osc.start(t);
    osc.stop(t + 1.35);
  }

  alarm() {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    for (let i = 0; i < 2; i++) {
      const osc = this.ctx.createOscillator();
      osc.type = "square";
      osc.frequency.value = 660;
      const g = this.ctx.createGain();
      g.gain.setValueAtTime(0.0001, t + i * 0.17);
      g.gain.exponentialRampToValueAtTime(0.035, t + i * 0.17 + 0.02);
      g.gain.exponentialRampToValueAtTime(0.0001, t + i * 0.17 + 0.12);
      osc.connect(g);
      g.connect(this.master);
      osc.start(t + i * 0.17);
      osc.stop(t + i * 0.17 + 0.13);
    }
  }

  upgrade() {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    const freqs = [392, 523.25, 659.25, 783.99];
    freqs.forEach((fr, i) => {
      const osc = this.ctx.createOscillator();
      osc.type = "sine";
      osc.frequency.value = fr;
      const g = this.ctx.createGain();
      g.gain.setValueAtTime(0.0001, t + i * 0.065);
      g.gain.exponentialRampToValueAtTime(0.035, t + i * 0.065 + 0.02);
      g.gain.exponentialRampToValueAtTime(0.0001, t + i * 0.065 + 0.35);
      osc.connect(g);
      g.connect(this.master);
      osc.start(t + i * 0.065);
      osc.stop(t + i * 0.065 + 0.36);
    });
  }

  uiClick() {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    osc.type = "square";
    osc.frequency.setValueAtTime(720, t);
    osc.frequency.exponentialRampToValueAtTime(980, t + 0.04);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.018, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.06);
    osc.connect(g);
    g.connect(this.master);
    osc.start(t);
    osc.stop(t + 0.07);
  }
}

import * as THREE from "three";

function screenMaterial(canvas, texture) {
  const mat = new THREE.MeshBasicMaterial({
    map: texture,
    transparent: false,
    toneMapped: false,
  });
  return mat;
}

export function createCockpit(camera, scene) {
  const group = new THREE.Group();
  group.visible = false;
  camera.add(group);
  scene.add(camera);

  const dark = new THREE.MeshBasicMaterial({ color: 0x080a0c });
  const mid = new THREE.MeshBasicMaterial({ color: 0x12171c });
  const edge = new THREE.MeshBasicMaterial({ color: 0x242c33 });
  const orange = new THREE.MeshBasicMaterial({ color: 0xff5a2d });
  const cyan = new THREE.MeshBasicMaterial({ color: 0x5ee7ff });
  const dimCyan = new THREE.MeshBasicMaterial({ color: 0x1d6f7e });

  const add = (geo, mat, x, y, z, rx = 0, ry = 0, rz = 0) => {
    const m = new THREE.Mesh(geo, mat);
    m.position.set(x, y, z);
    m.rotation.set(rx, ry, rz);
    group.add(m);
    return m;
  };

  // lower dash
  const dash = add(new THREE.BoxGeometry(1.42, 0.27, 0.5), dark, 0, -0.36, -0.56, 0.16);
  const dashTop = add(new THREE.BoxGeometry(1.32, 0.025, 0.45), mid, 0, -0.272, -0.55, 0.16);
  const dashEdge = add(new THREE.BoxGeometry(1.35, 0.018, 0.02), edge, 0, -0.255, -0.778, 0.16);
  add(new THREE.BoxGeometry(0.25, 0.028, 0.02), orange, 0, -0.252, -0.8, 0.16);

  // side console rails
  for (const side of [-1, 1]) {
    add(new THREE.BoxGeometry(0.09, 0.53, 0.36), dark, side * 0.62, -0.18, -0.49, 0.14, side * 0.15);
    add(new THREE.BoxGeometry(0.012, 0.35, 0.012), edge, side * 0.59, -0.14, -0.66, 0.14);
    add(new THREE.BoxGeometry(0.016, 0.11, 0.016), orange, side * 0.59, -0.1, -0.67, 0.14);
    add(new THREE.CylinderGeometry(0.016, 0.016, 0.33, 5), mid, side * 0.5, -0.25, -0.38, 0.22, 0, side * 0.24);
    add(new THREE.SphereGeometry(0.041, 7, 5), dark, side * 0.46, -0.125, -0.425);
  }

  // canopy pillars
  for (const side of [-1, 1]) {
    const pillar = add(
      new THREE.BoxGeometry(0.037, 0.83, 0.07),
      dark,
      side * 0.64,
      -0.02,
      -0.54,
      -0.05,
      side * -0.08,
      side * 0.09
    );
    add(new THREE.BoxGeometry(0.013, 0.78, 0.012), edge, side * 0.627, -0.02, -0.577, -0.05, side * -0.08, side * 0.09);
  }
  add(new THREE.BoxGeometry(1.24, 0.04, 0.05), dark, 0, 0.35, -0.57);
  add(new THREE.BoxGeometry(0.92, 0.012, 0.012), edge, 0, 0.329, -0.598);

  // guns / nose housing
  for (const side of [-1, 1]) {
    add(new THREE.CylinderGeometry(0.018, 0.024, 0.46, 6), mid, side * 0.27, -0.44, -0.92, Math.PI / 2);
    add(new THREE.CylinderGeometry(0.01, 0.014, 0.08, 5), edge, side * 0.27, -0.44, -1.18, Math.PI / 2);
  }

  // bolts / accent lights
  const boltGeo = new THREE.CylinderGeometry(0.006, 0.006, 0.004, 5);
  for (let i = 0; i < 12; i++) {
    add(boltGeo, edge, -0.55 + (i % 6) * 0.22, -0.255, -0.797, Math.PI / 2);
  }
  const ledGeo = new THREE.SphereGeometry(0.008, 4, 3);
  add(ledGeo, orange, 0.36, -0.27, -0.78);
  add(ledGeo, cyan, 0.39, -0.27, -0.78);
  add(ledGeo, dimCyan, 0.42, -0.27, -0.78);

  // instrument displays
  const displays = [];
  for (let i = 0; i < 2; i++) {
    const canvas = document.createElement("canvas");
    canvas.width = 256;
    canvas.height = 128;
    const ctx = canvas.getContext("2d");
    ctx.fillStyle = "#040b0d";
    ctx.fillRect(0, 0, 256, 128);
    const tex = new THREE.CanvasTexture(canvas);
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.minFilter = THREE.LinearFilter;
    tex.magFilter = THREE.LinearFilter;
    const mat = screenMaterial(canvas, tex);
    const x = i === 0 ? -0.32 : 0.32;
    const bezel = add(new THREE.BoxGeometry(0.32, 0.176, 0.01), edge, x, -0.285, -0.755, 0.16);
    const screen = add(new THREE.PlaneGeometry(0.285, 0.142), mat, x, -0.285, -0.747, 0.16);
    screen.renderOrder = 5;
    const glow = add(new THREE.PlaneGeometry(0.285, 0.142), new THREE.MeshBasicMaterial({
      color: i === 0 ? 0x5ee7ff : 0xff7d42,
      transparent: true,
      opacity: 0.035,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    }), x, -0.285, -0.744, 0.16);
    displays.push({ canvas, ctx, tex, screen, glow, side: i });
  }

  // center compass strip bezel
  const compass = add(new THREE.BoxGeometry(0.31, 0.05, 0.012), mid, 0, -0.245, -0.78, 0.16);
  add(new THREE.BoxGeometry(0.25, 0.008, 0.006), dimCyan, 0, -0.245, -0.788, 0.16);

  let drawTimer = 0;
  let bobT = 0;

  function drawDisplays(data) {
    const { speed, altitude, heat, overheat, missiles, target, hull } = data;
    for (const d of displays) {
      const { ctx, canvas } = d;
      const w = canvas.width;
      const h = canvas.height;
      ctx.clearRect(0, 0, w, h);
      ctx.fillStyle = "#031014";
      ctx.fillRect(0, 0, w, h);
      ctx.strokeStyle = "rgba(94,231,255,0.14)";
      ctx.lineWidth = 1;
      for (let x = 0; x < w; x += 16) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, h);
        ctx.stroke();
      }
      for (let y = 0; y < h; y += 16) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(w, y);
        ctx.stroke();
      }
      ctx.font = "10px monospace";
      ctx.fillStyle = "rgba(94,231,255,0.68)";
      ctx.fillText("AH-79 // SYS", 10, 16);

      if (d.side === 0) {
        ctx.fillStyle = "rgba(255,255,255,0.55)";
        ctx.font = "9px monospace";
        ctx.fillText("AIR DATA", 10, 34);
        ctx.fillStyle = "#9df2ff";
        ctx.font = "30px monospace";
        ctx.fillText(String(Math.round(speed)).padStart(3, "0"), 10, 67);
        ctx.font = "9px monospace";
        ctx.fillStyle = "rgba(94,231,255,0.7)";
        ctx.fillText("KTS", 78, 66);
        ctx.fillStyle = "#ffce9a";
        ctx.font = "20px monospace";
        ctx.fillText(String(Math.round(altitude)).padStart(3, "0"), 132, 67);
        ctx.fillStyle = "rgba(255,206,154,0.65)";
        ctx.font = "8px monospace";
        ctx.fillText("ALT M", 182, 66);
        ctx.strokeStyle = "rgba(94,231,255,0.32)";
        ctx.strokeRect(10, 79, w - 20, 7);
        ctx.fillStyle = hull > 50 ? "#5ee7ff" : hull > 25 ? "#ff8a45" : "#ff304c";
        ctx.fillRect(10, 79, (w - 20) * (hull / 100), 7);
        ctx.fillStyle = "rgba(255,255,255,0.38)";
        ctx.font = "8px monospace";
        ctx.fillText("HULL INTEGRITY", 10, 102);
      } else {
        ctx.fillStyle = "rgba(255,255,255,0.55)";
        ctx.font = "9px monospace";
        ctx.fillText("FIRE CONTROL", 10, 34);
        ctx.fillStyle = overheat ? "#ff304c" : "#ffbd87";
        ctx.font = "12px monospace";
        ctx.fillText(overheat ? "OVERHEAT" : "VULCAN RDY", 10, 54);
        ctx.fillStyle = "rgba(255,255,255,0.32)";
        ctx.font = "8px monospace";
        ctx.fillText("HEAT", 10, 73);
        ctx.fillStyle = overheat ? "#ff304c" : heat > 0.65 ? "#ff8a45" : "#5ee7ff";
        ctx.fillRect(10, 79, (w - 20) * Math.min(1, heat), 7);
        ctx.fillStyle = "rgba(255,255,255,0.55)";
        ctx.font = "9px monospace";
        ctx.fillText(`MSL ${String(missiles).padStart(2, "0")}`, 10, 106);
        ctx.fillStyle = target ? "#ff8a45" : "rgba(255,255,255,0.3)";
        ctx.font = "8px monospace";
        ctx.fillText(target ? "THREAT LOCKED" : "NO THREAT LOCK", 94, 106);
      }
      ctx.strokeStyle = "rgba(94,231,255,0.22)";
      ctx.strokeRect(1, 1, w - 2, h - 2);
      d.tex.needsUpdate = true;
    }
  }

  function update(dt, data) {
    bobT += dt;
    group.position.x = Math.sin(bobT * 0.9) * 0.0016;
    group.position.y = Math.sin(bobT * 1.4) * 0.0012;
    drawTimer -= dt;
    if (drawTimer <= 0) {
      drawTimer = 0.08;
      drawDisplays(data);
    }
    const pulse = 0.5 + Math.sin(bobT * 4.2) * 0.5;
    displays[0].glow.material.opacity = 0.025 + pulse * 0.02;
    displays[1].glow.material.opacity = 0.025 + (1 - pulse) * 0.02;
  }

  return {
    group,
    update,
    show() {
      group.visible = true;
    },
    hide() {
      group.visible = false;
    },
  };
}

import * as THREE from "three";
import { createCockpit } from "./cockpit.js";

const _forward = new THREE.Vector3();
const _right = new THREE.Vector3();
const _desired = new THREE.Vector3();
const _prev = new THREE.Vector3();
const _muzzle = new THREE.Vector3();
const _dir = new THREE.Vector3();

export const BASE_STATS = {
  speed: 46,
  damage: 22,
  fireInterval: 0.095,
  heatPerShot: 0.05,
  coolRate: 0.38,
  missileCap: 2,
  missileDamage: 470,
  missileTurn: 2.8,
  critChance: 0.04,
  maxHull: 100,
  repairPerKill: 0,
  regen: 0,
  spread: 0.0032,
};

export class PlayerController {
  constructor({ camera, canvas, world, effects, audio, isTouch }) {
    this.camera = camera;
    this.canvas = canvas;
    this.world = world;
    this.effects = effects;
    this.audio = audio;
    this.isTouch = isTouch;
    this.cockpit = createCockpit(camera, camera.parent || camera);

    this.pos = new THREE.Vector3(0, 48, 158);
    this.vel = new THREE.Vector3();
    this.yaw = 0;
    this.pitch = -0.06;
    this.roll = 0;
    this.shake = 0;
    this.recoil = 0;
    this.yawKick = 0;
    this.bobT = 0;
    this.altitudeInput = 0;
    this.keys = new Set();
    this.enabled = false;
    this.firing = false;
    this.locked = false;
    this.target = null;
    this.callbacks = {};
    this.lastCollision = 0;
    this.boundaryWarn = 0;
    this.overheatWarned = false;
    this.muzzleSide = 1;
    this.touchDrag = null;
    this.touchMove = { x: 0, y: 0 };
    this.touchAlt = 0;
    this.stats = { ...BASE_STATS };
    this.maxHull = this.stats.maxHull;
    this.hull = this.maxHull;
    this.heat = 0;
    this.overheat = false;
    this.fireTimer = 0;
    this.missiles = this.stats.missileCap;
    this.missileTimer = 0;
    this.missileLaunchCd = 0;
    this.shots = 0;
    this.hits = 0;
    this.scanActive = false;
    this.lastDamageAt = -100;
    this.statsDirty = true;

    this._bindInput();
  }

  setCallbacks(callbacks) {
    this.callbacks = callbacks;
  }

  resetRun() {
    this.stats = { ...BASE_STATS };
    this.maxHull = this.stats.maxHull;
    this.hull = this.maxHull;
    this.heat = 0;
    this.overheat = false;
    this.fireTimer = 0;
    this.missiles = this.stats.missileCap;
    this.missileTimer = 0;
    this.missileLaunchCd = 0;
    this.shots = 0;
    this.hits = 0;
    this.pos.set(0, 49, 158);
    this.vel.set(0, 0, 0);
    this.yaw = 0;
    this.pitch = -0.055;
    this.roll = 0;
    this.shake = 0;
    this.recoil = 0;
    this.lastDamageAt = -100;
    this.enabled = false;
    this.firing = false;
    this.target = null;
    this.statsDirty = true;
  }

  applyStats() {
    this.maxHull = this.stats.maxHull;
    this.hull = Math.min(this.hull, this.maxHull);
    this.missiles = Math.min(this.missiles, this.stats.missileCap);
    this.statsDirty = false;
  }

  start() {
    this.enabled = true;
    this.cockpit.show();
    this.firing = false;
  }

  stop() {
    this.enabled = false;
    this.firing = false;
    this.keys.clear();
    this.touchMove.x = this.touchMove.y = 0;
    this.touchAlt = 0;
    this.resetJoystick();
  }

  requestPointerLock() {
    if (this.isTouch) return;
    try {
      const p = this.canvas.requestPointerLock?.();
      if (p?.catch) p.catch(() => {});
    } catch {
      /* pointer lock is optional */
    }
  }

  _bindInput() {
    const canvas = this.canvas;

    window.addEventListener("keydown", (e) => {
      if (!this.enabled) return;
      const code = e.code;
      if (["KeyW", "KeyA", "KeyS", "KeyD", "KeyR", "KeyF", "ShiftLeft", "ShiftRight", "Space"].includes(code)) {
        e.preventDefault();
      }
      this.keys.add(code);
    });
    window.addEventListener("keyup", (e) => {
      this.keys.delete(e.code);
    });

    canvas.addEventListener("mousedown", (e) => {
      if (!this.enabled) return;
      if (e.button === 0) {
        this.firing = true;
        if (!this.isTouch && document.pointerLockElement !== canvas) this.requestPointerLock();
      } else if (e.button === 2) {
        this.launchMissile();
      }
    });

    window.addEventListener("mouseup", (e) => {
      if (e.button === 0) this.firing = false;
    });
    window.addEventListener("blur", () => {
      this.firing = false;
      this.keys.clear();
      this.touchMove.x = this.touchMove.y = 0;
      this.touchAlt = 0;
      this.resetJoystick();
    });

    window.addEventListener("contextmenu", (e) => {
      if (this.enabled) e.preventDefault();
    });

    window.addEventListener("mousemove", (e) => {
      if (!this.enabled) return;
      const locked = document.pointerLockElement === canvas;
      if (!locked && e.buttons !== 1 && e.buttons !== 2) return;
      const mx = e.movementX || 0;
      const my = e.movementY || 0;
      this.yaw -= mx * 0.00215;
      this.pitch -= my * 0.00215;
      this.pitch = THREE.MathUtils.clamp(this.pitch, -1.25, 1.25);
      this.yawKick = THREE.MathUtils.clamp(this.yawKick - mx * 0.00005, -0.015, 0.015);
    });

    document.addEventListener("pointerlockchange", () => {
      this.locked = document.pointerLockElement === canvas;
      if (this.callbacks.onPointerLockChange) this.callbacks.onPointerLockChange(this.locked);
    });

    // touch look
    canvas.addEventListener(
      "pointerdown",
      (e) => {
        if (e.pointerType !== "touch" || !this.enabled) return;
        this.touchDrag = { id: e.pointerId, x: e.clientX, y: e.clientY };
        canvas.setPointerCapture?.(e.pointerId);
        const hint = document.getElementById("look-hint");
        if (hint) hint.classList.remove("show");
      },
      { passive: true }
    );
    canvas.addEventListener(
      "pointermove",
      (e) => {
        if (!this.touchDrag || e.pointerId !== this.touchDrag.id || !this.enabled) return;
        const dx = e.clientX - this.touchDrag.x;
        const dy = e.clientY - this.touchDrag.y;
        this.touchDrag.x = e.clientX;
        this.touchDrag.y = e.clientY;
        this.yaw -= dx * 0.0041;
        this.pitch -= dy * 0.0041;
        this.pitch = THREE.MathUtils.clamp(this.pitch, -1.25, 1.25);
      },
      { passive: true }
    );
    const endTouch = (e) => {
      if (this.touchDrag && e.pointerId === this.touchDrag.id) this.touchDrag = null;
    };
    canvas.addEventListener("pointerup", endTouch);
    canvas.addEventListener("pointercancel", endTouch);

    this._bindTouchControls();
  }

  _bindTouchControls() {
    const zone = document.getElementById("joystick-zone");
    const knob = document.getElementById("joystick-knob");
    const fire = document.getElementById("touch-fire");
    const missile = document.getElementById("touch-missile");
    const up = document.getElementById("touch-up");
    const down = document.getElementById("touch-down");

    if (zone) {
      let joystickId = null;
      let centerX = 0;
      let centerY = 0;
      let radius = 42;

      const updateStick = (e) => {
        let dx = e.clientX - centerX;
        let dy = e.clientY - centerY;
        const len = Math.hypot(dx, dy);
        if (len > radius) {
          dx = (dx / len) * radius;
          dy = (dy / len) * radius;
        }
        this.touchMove.x = dx / radius;
        this.touchMove.y = -dy / radius;
        if (knob) knob.style.transform = `translate(${dx}px, ${dy}px)`;
      };

      zone.addEventListener("pointerdown", (e) => {
        if (!this.enabled) return;
        e.preventDefault();
        const rect = zone.querySelector(".joystick-ring").getBoundingClientRect();
        centerX = rect.left + rect.width / 2;
        centerY = rect.top + rect.height / 2;
        radius = rect.width * 0.36;
        joystickId = e.pointerId;
        zone.setPointerCapture?.(e.pointerId);
        updateStick(e);
        const hint = document.getElementById("look-hint");
        if (hint) hint.classList.remove("show");
      });
      zone.addEventListener("pointermove", (e) => {
        if (e.pointerId !== joystickId) return;
        e.preventDefault();
        updateStick(e);
      });
      const end = (e) => {
        if (e.pointerId !== joystickId) return;
        joystickId = null;
        this.touchMove.x = this.touchMove.y = 0;
        this.resetJoystick();
      };
      zone.addEventListener("pointerup", end);
      zone.addEventListener("pointercancel", end);
    }

    if (fire) {
      fire.addEventListener("pointerdown", (e) => {
        if (!this.enabled) return;
        e.preventDefault();
        fire.setPointerCapture?.(e.pointerId);
        this.firing = true;
        fire.classList.add("pressed");
      });
      const release = () => {
        this.firing = false;
        fire.classList.remove("pressed");
      };
      fire.addEventListener("pointerup", release);
      fire.addEventListener("pointercancel", release);
      fire.addEventListener("pointerleave", (e) => {
        if (e.buttons === 0) release();
      });
    }

    if (missile) {
      missile.addEventListener("pointerdown", (e) => {
        if (!this.enabled) return;
        e.preventDefault();
        this.launchMissile();
      });
    }

    for (const [el, value] of [
      [up, 1],
      [down, -1],
    ]) {
      if (!el) continue;
      el.addEventListener("pointerdown", (e) => {
        if (!this.enabled) return;
        e.preventDefault();
        this.touchAlt = value;
        el.setPointerCapture?.(e.pointerId);
        el.classList.add("pressed");
      });
      const release = () => {
        if (this.touchAlt === value) this.touchAlt = 0;
        el.classList.remove("pressed");
      };
      el.addEventListener("pointerup", release);
      el.addEventListener("pointercancel", release);
      el.addEventListener("pointerleave", release);
    }
  }

  resetJoystick() {
    const knob = document.getElementById("joystick-knob");
    if (knob) knob.style.transform = "translate(0px, 0px)";
  }

  addShake(amount) {
    this.shake = Math.min(0.065, this.shake + amount);
  }

  damage(amount, source = "hit") {
    if (this.hull <= 0) return;
    this.hull = Math.max(0, this.hull - amount);
    this.addShake(0.018);
    if (this.callbacks.onDamage) this.callbacks.onDamage(amount, this.hull, source);
    if (this.hull <= 0 && this.callbacks.onDeath) this.callbacks.onDeath();
  }

  heal(amount) {
    if (amount <= 0) return 0;
    const before = this.hull;
    this.hull = Math.min(this.maxHull, this.hull + amount);
    return this.hull - before;
  }

  update(dt, time) {
    if (!this.enabled) {
      this.audio.updateEngine(0, false, false);
      return;
    }

    this.bobT += dt;
    this.fireTimer -= dt;
    this.missileLaunchCd -= dt;

    const boost = this.keys.has("ShiftLeft") || this.keys.has("ShiftRight");
    let thrust = 0;
    let strafe = 0;
    if (this.keys.has("KeyW")) thrust += 1;
    if (this.keys.has("KeyS")) thrust -= 0.65;
    if (this.keys.has("KeyA")) strafe -= 1;
    if (this.keys.has("KeyD")) strafe += 1;
    if (this.isTouch) {
      thrust += this.touchMove.y;
      strafe += this.touchMove.x;
    }
    thrust = THREE.MathUtils.clamp(thrust, -1, 1);
    strafe = THREE.MathUtils.clamp(strafe, -1, 1);
    this.altitudeInput = 0;
    if (this.keys.has("KeyR") || this.keys.has("Space")) this.altitudeInput += 1;
    if (this.keys.has("KeyF")) this.altitudeInput -= 1;
    if (this.isTouch) this.altitudeInput += this.touchAlt;
    this.altitudeInput = THREE.MathUtils.clamp(this.altitudeInput, -1, 1);

    const speed = this.stats.speed * (boost ? 1.58 : 1);

    const cp = Math.cos(this.pitch * 0.58);
    _forward.set(
      -Math.sin(this.yaw) * cp,
      Math.sin(this.pitch * 0.58) * 0.85,
      -Math.cos(this.yaw) * cp
    );
    _right.set(Math.cos(this.yaw), 0, -Math.sin(this.yaw));

    _desired.set(0, 0, 0);
    _desired.addScaledVector(_forward, thrust * speed);
    _desired.addScaledVector(_right, strafe * speed * 0.74);
    _desired.y += this.altitudeInput * speed * 0.64;

    const accel = thrust !== 0 || strafe !== 0 || this.altitudeInput !== 0 ? (boost ? 2.7 : 3.6) : 2.1;
    this.vel.lerp(_desired, 1 - Math.exp(-dt * accel));
    if (Math.abs(thrust) < 0.01 && Math.abs(strafe) < 0.01 && Math.abs(this.altitudeInput) < 0.01) {
      this.vel.multiplyScalar(Math.exp(-dt * 0.72));
    }

    _prev.copy(this.pos);
    this.pos.addScaledVector(this.vel, dt);

    const bX = 246;
    const bZ = 246;
    const beforeX = this.pos.x;
    const beforeZ = this.pos.z;
    this.pos.x = THREE.MathUtils.clamp(this.pos.x, -bX, bX);
    this.pos.z = THREE.MathUtils.clamp(this.pos.z, -bZ, bZ);
    this.pos.y = THREE.MathUtils.clamp(this.pos.y, 6.5, 105);
    const atBoundary = beforeX !== this.pos.x || beforeZ !== this.pos.z || this.pos.y === 105 || this.pos.y === 6.5;
    this.boundaryWarn = atBoundary ? 0.45 : Math.max(0, this.boundaryWarn - dt);

    const building = this.world.getBuildingAt(this.pos.x, this.pos.z, 1.35);
    if (building && this.pos.y < 1.28 + building.height + 1.6) {
      this.pos.copy(_prev);
      this.vel.multiplyScalar(-0.12);
      if (time - this.lastCollision > 0.9) {
        this.lastCollision = time;
        this.damage(8, "collision");
        this.addShake(0.035);
      }
    }

    const targetRoll = -strafe * 0.12 - this.yawKick * 2.2;
    this.roll += (targetRoll - this.roll) * Math.min(1, dt * 4.6);
    this.yawKick *= Math.exp(-dt * 3.8);
    this.shake *= Math.exp(-dt * 5.4);
    this.recoil *= Math.exp(-dt * 11);

    this.heat = Math.max(0, this.heat - this.stats.coolRate * dt);
    if (this.overheat && this.heat <= 0.24) {
      this.overheat = false;
      this.overheatWarned = false;
      if (this.callbacks.onHeatReady) this.callbacks.onHeatReady();
    }

    if (this.missiles < this.stats.missileCap) {
      if (this.missileTimer <= 0) this.missileTimer = 5.1;
      this.missileTimer -= dt;
      if (this.missileTimer <= 0) {
        this.missiles++;
        if (this.missiles < this.stats.missileCap) this.missileTimer = 5.1;
        else this.missileTimer = 0;
        if (this.callbacks.onMissileReload) this.callbacks.onMissileReload(this.missiles);
      }
    } else {
      this.missileTimer = 0;
    }

    this._updateCamera(dt, time);
    this._updateCockpit(dt);

    if (time - this.lastDamageAt > 7.5) {
      if (this.stats.regen > 0) this.heal(this.stats.regen * dt);
    }

    if (this.firing) this._tryFire(time);

    this.audio.updateEngine(this.vel.length(), boost, true);
  }

  _updateCamera(dt, time) {
    const shakeX = this.shake * (Math.sin(time * 61.3) * 0.6 + Math.sin(time * 37.7) * 0.4);
    const shakeY = this.shake * (Math.sin(time * 53.1) * 0.55 + Math.sin(time * 29.2) * 0.45);
    const shakeZ = this.shake * Math.sin(time * 43.5) * 0.9;
    const hover = Math.sin(this.bobT * 1.25) * 0.06;

    this.camera.position.set(
      this.pos.x + shakeX * 0.16,
      this.pos.y + hover + shakeY * 0.16,
      this.pos.z
    );
    this.camera.rotation.set(
      this.pitch + this.recoil + shakeY * 0.45,
      this.yaw + shakeX * 0.45,
      this.roll + shakeZ,
      "YXZ"
    );
    this.camera.updateMatrixWorld(true);
  }

  _updateCockpit(dt) {
    this.cockpit.update(dt, {
      speed: this.vel.length() * 1.95,
      altitude: this.pos.y,
      heat: this.heat,
      overheat: this.overheat,
      missiles: this.missiles,
      target: this.target,
      hull: (this.hull / this.maxHull) * 100,
    });
  }

  _tryFire(time) {
    if (this.overheat || this.fireTimer > 0 || !this.enabled) return;
    this.fireTimer = this.stats.fireInterval;
    this.heat = Math.min(1, this.heat + this.stats.heatPerShot);
    if (this.heat >= 1) {
      this.heat = 1;
      this.overheat = true;
      this.audio.overheat();
      if (this.callbacks.onOverheat) this.callbacks.onOverheat();
    }

    this.muzzleSide *= -1;
    _muzzle.set(this.muzzleSide * 0.27, -0.4, -1.1);
    this.camera.localToWorld(_muzzle);
    this.camera.getWorldDirection(_dir);
    const spread = this.stats.spread + this.heat * 0.0035 + this.vel.length() * 0.00002;
    _dir.x += (Math.random() - 0.5) * spread * 2;
    _dir.y += (Math.random() - 0.5) * spread * 2;
    _dir.z += (Math.random() - 0.5) * spread * 2;
    _dir.normalize();

    this.shots++;
    this.recoil += 0.0018 + Math.random() * 0.0012;
    this.addShake(0.0018);
    this.effects.muzzle(_muzzle, _dir);
    this.audio.gun();
    if (this.callbacks.onShot) this.callbacks.onShot(_muzzle.clone(), _dir.clone(), this.stats);
  }

  launchMissile() {
    if (!this.enabled) return false;
    if (this.missileLaunchCd > 0) return false;
    if (this.missiles <= 0) {
      if (this.callbacks.onNoMissiles) this.callbacks.onNoMissiles();
      return false;
    }
    this.missiles--;
    this.missileLaunchCd = 0.38;
    if (this.missiles < this.stats.missileCap && this.missileTimer <= 0) this.missileTimer = 5.1;
    this.addShake(0.014);
    this.audio.missile();
    _muzzle.set(0.34, -0.31, -0.95);
    this.camera.localToWorld(_muzzle);
    this.camera.getWorldDirection(_dir);
    if (this.callbacks.onMissile) {
      this.callbacks.onMissile(
        _muzzle.clone(),
        _dir.clone(),
        this.target,
        this.stats.missileDamage,
        this.stats.missileTurn
      );
    }
    return true;
  }

  registerHit() {
    this.hits++;
  }

  addUpgradeStats(mutator) {
    mutator(this.stats, this);
    this.applyStats();
  }

  get isMoving() {
    return this.vel.lengthSq() > 4;
  }
}

