const byCat = {
  WEAPON: UPGRADES.filter((u) => u.cat === "WEAPON"),
  AIRFRAME: UPGRADES.filter((u) => u.cat === "AIRFRAME"),
  SYSTEM: UPGRADES.filter((u) => u.cat === "SYSTEM"),
};

export function getUpgradeChoices() {
  const cats = ["WEAPON", "AIRFRAME", "SYSTEM"];
  return cats.map((cat) => {
    const pool = byCat[cat];
    return pool[Math.floor(Math.random() * pool.length)];
  });
}

export function upgradeDisplayName(id) {
  const u = UPGRADES.find((x) => x.id === id);
  return u ? u.name : id.toUpperCase();
}

import * as THREE from "three";

const _project = new THREE.Vector3();

function $(id) {
  return document.getElementById(id);
}

function formatScore(n) {
  return Math.max(0, Math.floor(n)).toString().padStart(6, "0");
}

function formatTime(seconds) {
  const s = Math.max(0, Math.floor(seconds));
  return `${String(Math.floor(s / 60)).padStart(2, "0")}:${String(s % 60).padStart(2, "0")}`;
}

export class GameUI {
  constructor() {
    this.menu = $("menu");
    this.hud = $("hud");
    this.upgrade = $("upgrade");
    this.pause = $("pause");
    this.gameover = $("gameover");
    this.briefing = $("briefing");
    this.transition = $("transition");
    this.healthFlash = $("damage-vignette");
    this.hitmarker = $("hitmarker");
    this.reticle = $("reticle");
    this.targetPanel = $("target-panel");
    this.lockbox = $("lockbox");
    this.killFeed = $("kill-feed");
    this.warningBanner = $("warning-banner");
    this.warningText = $("warning-text");
    this.banner = $("wave-banner");
    this.combo = $("combo");
    this.radar = $("radar");
    this.radarCtx = this.radar.getContext("2d");
    this.perksLine = $("perks-line");
    this.deployNextBtn = $("deploy-next-btn");
    this.upgradeCards = $("upgrade-cards");
    this.upgradeTip = $("upgrade-tip");
    this.selectedUpgrade = null;
    this._warningToken = 0;
    this._bannerTimer = 0;
    this._feedTimers = [];
    this._radarTimer = 0;
    this._damageTimer = 0;
    this._hitTimer = 0;
    this._targetName = "";
    this._lastHull = 100;
    this._lastCity = 100;
    this._lastScore = -1;
    this._lastTime = "";
    this._lastMissiles = -1;
    this._lastHeatState = "";
    this._lastTargetHp = -1;
    this._best = this.loadBest();
    this.updateMenuBest();
  }

  loadBest() {
    try {
      const raw = localStorage.getItem("rotor-titan-best");
      if (!raw) return { score: 0, wave: 0 };
      const data = JSON.parse(raw);
      return { score: Number(data.score) || 0, wave: Number(data.wave) || 0 };
    } catch {
      return { score: 0, wave: 0 };
    }
  }

  saveBest(score, wave) {
    if (score > this._best.score) {
      this._best = { score, wave };
      try {
        localStorage.setItem("rotor-titan-best", JSON.stringify(this._best));
      } catch {
        /* storage may be unavailable */
      }
      this.updateMenuBest();
      return true;
    }
    return false;
  }

  updateMenuBest() {
    const score = $("menu-best");
    const wave = $("menu-best-wave");
    if (score) score.textContent = this._best.score > 0 ? this._best.score.toLocaleString("en-US") : "0";
    if (wave) wave.textContent = this._best.wave > 0 ? `WAVE ${String(this._best.wave).padStart(2, "0")} CLEARED` : "NO RECORD";
  }

  showMenu() {
    this.menu.classList.remove("hidden");
    this.hud.classList.add("hidden");
    this.upgrade.classList.add("hidden");
    this.pause.classList.add("hidden");
    this.gameover.classList.add("hidden");
    this.menu.setAttribute("aria-hidden", "false");
    this.hud.setAttribute("aria-hidden", "true");
    this.clearFeed();
  }

  hideMenu() {
    this.menu.classList.add("hidden");
    this.menu.setAttribute("aria-hidden", "true");
  }

  showHud() {
    this.hud.classList.remove("hidden");
    this.hud.setAttribute("aria-hidden", "false");
  }

  hideHud() {
    this.hud.classList.add("hidden");
    this.hud.setAttribute("aria-hidden", "true");
  }

  showBriefing() {
    this.briefing.classList.remove("hidden");
    this.briefing.setAttribute("aria-hidden", "false");
  }

  hideBriefing() {
    this.briefing.classList.add("hidden");
    this.briefing.setAttribute("aria-hidden", "true");
  }

  showPause() {
    this.pause.classList.remove("hidden");
    this.pause.setAttribute("aria-hidden", "false");
  }

  hidePause() {
    this.pause.classList.add("hidden");
    this.pause.setAttribute("aria-hidden", "true");
  }

  showGameOver(reason, game, player, isNewBest) {
    const title = $("gameover-title");
    const kicker = $("gameover-kicker");
    const text = $("gameover-text");
    if (reason === "city") {
      kicker.textContent = "SECTOR 07 OVERRUN";
      title.innerHTML = "CITY<br><span>LOST</span>";
      text.textContent = "The kaiju have flattened the evacuation corridor. All rotor units are ordered to withdraw.";
    } else {
      kicker.textContent = "SIGNAL LOST";
      title.innerHTML = "AIRFRAME<br><span>LOST</span>";
      text.textContent = "The AH-79 is down. Sector 07 remains under kaiju control. Sky Control is scrambling another crew.";
    }
    $("final-score").textContent = Math.floor(game.score).toLocaleString("en-US");
    $("final-wave").textContent = Math.max(0, game.wave - 1);
    $("final-kills").textContent = game.kills;
    $("final-accuracy").textContent = `${player.shots > 0 ? Math.round((player.hits / player.shots) * 100) : 0}%`;
    $("gameover-best").textContent = isNewBest ? "NEW PERSONAL BEST" : `PERSONAL BEST ${this._best.score.toLocaleString("en-US")}`;
    this.gameover.classList.remove("hidden");
    this.gameover.setAttribute("aria-hidden", "false");
    this.lockbox.classList.remove("active");
    this.targetPanel.classList.remove("active");
    this.reticle.classList.remove("target");
  }

  setTransition(active) {
    this.transition.classList.toggle("active", active);
  }

  resetHud() {
    this.clearFeed();
    this.hideWarning();
    this.combo.classList.remove("active");
    this.targetPanel.classList.remove("active");
    this.lockbox.classList.remove("active");
    this.banner.classList.remove("show");
    this._lastScore = -1;
    this._lastHull = -1;
    this._lastCity = -1;
    this._lastMissiles = -1;
    this._targetName = "";
  }

  updatePlayHud(game, player) {
    const score = Math.floor(game.score);
    if (score !== this._lastScore) {
      this._lastScore = score;
      $("score").textContent = formatScore(score);
    }
    if ($("wave").textContent !== String(game.wave).padStart(2, "0")) {
      $("wave").textContent = String(game.wave).padStart(2, "0");
    }

    const city = Math.max(0, Math.min(100, Math.round(game.cityIntegrity)));
    if (city !== this._lastCity) {
      this._lastCity = city;
      $("city-pct").textContent = `${city}%`;
      const fill = $("city-bar-fill");
      fill.style.width = `${city}%`;
      fill.classList.toggle("warn", city <= 55 && city > 28);
      fill.classList.toggle("critical", city <= 28);
      const state = $("city-state");
      state.textContent = city > 70 ? "STABLE" : city > 35 ? "DAMAGED" : "CRITICAL";
      state.classList.toggle("warn", city <= 70 && city > 35);
      state.classList.toggle("critical", city <= 35);
    }

    const alt = Math.round(player.pos.y);
    const speed = Math.round(player.vel.length() * 1.95);
    $("alt").textContent = String(alt).padStart(3, "0");
    $("spd").textContent = String(speed).padStart(3, "0");
    const hull = Math.max(0, Math.round((player.hull / player.maxHull) * 100));
    if (hull !== this._lastHull) {
      this._lastHull = hull;
      $("hull-pct").textContent = String(hull).padStart(3, "0");
      const fill = $("hull-fill");
      fill.style.width = `${hull}%`;
      fill.classList.toggle("warn", hull <= 55 && hull > 25);
      fill.classList.toggle("critical", hull <= 25);
    }

    const heading = ((player.yaw * 180) / Math.PI + 360) % 360;
    $("heading").textContent = `HDG ${String(Math.round(heading)).padStart(3, "0")}`;

    const heat = Math.round(player.heat * 100);
    const heatFill = $("heat-fill");
    heatFill.style.width = `${heat}%`;
    heatFill.classList.toggle("hot", heat > 55 && heat < 100);
    heatFill.classList.toggle("over", player.overheat);
    let heatState = "NOMINAL";
    if (player.overheat) heatState = "OVERHEAT";
    else if (heat > 70) heatState = "CRITICAL";
    else if (heat > 40) heatState = "WARM";
    if (heatState !== this._lastHeatState) {
      this._lastHeatState = heatState;
      $("heat-state").textContent = heatState;
    }

    const missiles = player.missiles;
    if (missiles !== this._lastMissiles) {
      this._lastMissiles = missiles;
      $("missile-count").textContent = String(missiles).padStart(2, "0");
      const touch = $("touch-missile-count");
      if (touch) touch.textContent = String(missiles).padStart(2, "0");
      document.querySelector(".missile-line")?.classList.toggle("empty", missiles <= 0);
    }
    const mslState = $("missile-state");
    mslState.textContent = missiles > 0 ? (player.missileTimer > 0 && missiles < player.stats.missileCap ? "RELOAD" : "READY") : "EMPTY";

    const hostiles = game.entities.filter((e) => !e.dead).length;
    $("hostiles").textContent = `${String(hostiles).padStart(2, "0")} HOSTILE${hostiles === 1 ? "" : "S"}`;
    const t = formatTime(game.waveElapsed);
    if (t !== this._lastTime) {
      this._lastTime = t;
      $("objective-time").textContent = t;
    }
    const objective = $("objective-main");
    if (game.state === "clearing") objective.textContent = "SECTOR CLEAR";
    else if (game.entities.some((e) => !e.dead && e.isFlyer)) objective.textContent = "NEUTRALIZE ALL KAIJU";
    else objective.textContent = "NEUTRALIZE ALL KAIJU";

    const warning = $("boundary-warning");
    if (warning) warning.classList.toggle("show", player.boundaryWarn > 0);

    const retOverheat = player.overheat;
    this.reticle.classList.toggle("overheat", retOverheat);
    $("reticle-label").textContent = retOverheat ? "BARREL OVERHEAT" : player.target ? "TARGET LOCKED" : "30MM VULCAN";

    this.updateCombo(game);
    this.updateRadar(game, player);
  }

  updateCombo(game) {
    if (game.combo > 1) {
      this.combo.classList.add("active");
      $("combo-value").textContent = `x${game.combo}`;
      $("combo-fill").style.width = `${Math.max(0, Math.min(1, game.comboTimer / 2.6)) * 100}%`;
    } else {
      this.combo.classList.remove("active");
    }
  }

  updateTarget(target, player) {
    if (!target || target.dead) {
      this.targetPanel.classList.remove("active");
      this.lockbox.classList.remove("active");
      this.reticle.classList.remove("target");
      this._targetName = "";
      return;
    }

    const center = target.center;
    this.targetPanel.classList.add("active");
    this.reticle.classList.add("target");

    if (target.name !== this._targetName) {
      this._targetName = target.name;
      $("target-name").textContent = target.cfg.name;
      $("target-class").textContent = target.cfg.classLabel;
    }
    const hp = Math.max(0, Math.round((target.hp / target.maxHp) * 100));
    if (hp !== this._lastTargetHp) {
      this._lastTargetHp = hp;
      $("target-hp-fill").style.width = `${hp}%`;
      $("target-hp-text").textContent = `${hp}%`;
    }

    const distance = player.camera.position.distanceTo(center);
    $("target-range").textContent = `${Math.round(distance).toString().padStart(3, "0")} M`;

    _project.copy(center).project(player.camera);
    const inFront = _project.z > -1 && _project.z < 1;
    if (!inFront) {
      this.lockbox.classList.remove("active");
      return;
    }
    const x = (_project.x * 0.5 + 0.5) * window.innerWidth;
    const y = (-_project.y * 0.5 + 0.5) * window.innerHeight;
    if (x < -120 || y < -120 || x > window.innerWidth + 120 || y > window.innerHeight + 120) {
      this.lockbox.classList.remove("active");
      return;
    }
    const pxPerUnit = window.innerHeight / (2 * Math.tan((player.camera.fov * Math.PI) / 360));
    const size = Math.max(42, Math.min(300, (target.radius * 2 * pxPerUnit) / Math.max(1, distance) * 1.15));
    this.lockbox.style.left = `${x}px`;
    this.lockbox.style.top = `${y}px`;
    this.lockbox.style.width = `${size}px`;
    this.lockbox.style.height = `${size}px`;
    this.lockbox.classList.add("active");
    this.lockbox.classList.toggle("ready", player.missiles > 0);
    $("lock-tag").textContent = player.missiles > 0 ? "LOCK" : "TRACK";
  }

  updateRadar(game, player) {
    this._radarTimer -= 1 / 60;
    if (this._radarTimer > 0) return;
    this._radarTimer = 0.075;

    const ctx = this.radarCtx;
    const w = 220;
    const h = 220;
    const cx = w / 2;
    const cy = h / 2;
    const radius = 99;
    const range = 230;
    const scale = radius / range;
    const yaw = player.yaw;
    const cos = Math.cos(yaw);
    const sin = Math.sin(yaw);

    ctx.clearRect(0, 0, w, h);
    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, cy, radius, 0, Math.PI * 2);
    ctx.clip();

    const bg = ctx.createRadialGradient(cx, cy, 3, cx, cy, radius);
    bg.addColorStop(0, "rgba(10,25,30,0.52)");
    bg.addColorStop(0.7, "rgba(4,11,15,0.52)");
    bg.addColorStop(1, "rgba(2,6,8,0.7)");
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, w, h);

    // city grid
    if (game.world) {
      for (const b of game.world.buildings) {
        if (b.destroyed) continue;
        const dx = b.x - player.pos.x;
        const dz = b.z - player.pos.z;
        const sx = cx + (dx * cos - dz * sin) * scale;
        const sy = cy + (dx * sin + dz * cos) * scale;
        if ((sx - cx) ** 2 + (sy - cy) ** 2 > radius * radius) continue;
        ctx.fillStyle = "rgba(105,132,144,0.13)";
        const bw = Math.max(1.1, b.width * scale * 0.55);
        const bh = Math.max(1.1, b.depth * scale * 0.55);
        ctx.fillRect(sx - bw / 2, sy - bh / 2, bw, bh);
      }
    }

    // rings
    ctx.strokeStyle = "rgba(94,231,255,0.14)";
    ctx.lineWidth = 1;
    for (let i = 1; i <= 3; i++) {
      ctx.beginPath();
      ctx.arc(cx, cy, (radius / 3) * i, 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.beginPath();
    ctx.moveTo(cx - radius, cy);
    ctx.lineTo(cx + radius, cy);
    ctx.moveTo(cx, cy - radius);
    ctx.lineTo(cx, cy + radius);
    ctx.stroke();
    ctx.strokeStyle = "rgba(94,231,255,0.3)";
    ctx.beginPath();
    ctx.arc(cx, cy, radius - 1, 0, Math.PI * 2);
    ctx.stroke();

    // enemies
    for (const e of game.entities) {
      if (e.dead) continue;
      const p = e.center;
      const dx = p.x - player.pos.x;
      const dz = p.z - player.pos.z;
      let sx = cx + (dx * cos - dz * sin) * scale;
      let sy = cy + (dx * sin + dz * cos) * scale;
      let outside = false;
      const d = Math.hypot(sx - cx, sy - cy);
      if (d > radius - 5) {
        const f = (radius - 5) / d;
        sx = cx + (sx - cx) * f;
        sy = cy + (sy - cy) * f;
        outside = true;
      }
      const color = e.isFlyer ? "#5ee7ff" : "#ff5a2d";
      ctx.fillStyle = outside ? `${color}99` : color;
      ctx.beginPath();
      ctx.arc(sx, sy, e.isFlyer ? 2.4 : 3.8, 0, Math.PI * 2);
      ctx.fill();
      if (!outside && e === player.target) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.arc(sx, sy, 7 + Math.sin(performance.now() / 180) * 1.4, 0, Math.PI * 2);
        ctx.stroke();
      }
    }

    // player arrow
    ctx.save();
    ctx.translate(cx, cy);
    ctx.fillStyle = "#f3f7fa";
    ctx.shadowColor = "#5ee7ff";
    ctx.shadowBlur = 7;
    ctx.beginPath();
    ctx.moveTo(0, -6);
    ctx.lineTo(4.5, 5);
    ctx.lineTo(0, 2.6);
    ctx.lineTo(-4.5, 5);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
    ctx.restore();

    // compass ticks
    ctx.fillStyle = "rgba(255,255,255,0.32)";
    ctx.font = "7px monospace";
    ctx.textAlign = "center";
    ctx.fillText("N", cx, 9);
    ctx.fillText("E", w - 8, cy + 3);
    ctx.fillText("S", cx, h - 3);
    ctx.fillText("W", 8, cy + 3);
  }

  hitMarker(crit = false) {
    const hm = this.hitmarker;
    hm.classList.remove("show", "crit");
    void hm.offsetWidth;
    hm.classList.add("show");
    if (crit) hm.classList.add("crit");
    clearTimeout(this._hitTimer);
    this._hitTimer = setTimeout(() => hm.classList.remove("show", "crit"), 300);
  }

  damageFlash(strong = false) {
    if (performance.now() - this._damageTimer < 140) return;
    this._damageTimer = performance.now();
    this.healthFlash.classList.remove("flash");
    void this.healthFlash.offsetWidth;
    this.healthFlash.style.opacity = strong ? "1" : "0.65";
    this.healthFlash.classList.add("flash");
  }

  feed(text, tone = "kill") {
    const item = document.createElement("div");
    item.className = "feed-item";
    item.innerHTML = text;
    if (tone === "danger") item.style.borderColor = "#ff304c";
    this.killFeed.prepend(item);
    while (this.killFeed.children.length > 5) this.killFeed.lastElementChild.remove();
    const timer = setTimeout(() => {
      item.classList.add("out");
      setTimeout(() => item.remove(), 620);
    }, 3400);
    this._feedTimers.push(timer);
  }

  clearFeed() {
    this.killFeed.innerHTML = "";
    for (const t of this._feedTimers) clearTimeout(t);
    this._feedTimers = [];
  }

  showBanner(kicker, main, sub, duration = 3000) {
    const el = this.banner;
    $("banner-kicker").textContent = kicker;
    $("banner-main").textContent = main;
    $("banner-sub").textContent = sub;
    el.classList.remove("show");
    void el.offsetWidth;
    el.classList.add("show");
    clearTimeout(this._bannerTimer);
    this._bannerTimer = setTimeout(() => el.classList.remove("show"), duration);
  }

  showWarning(text, duration = 1800) {
    this._warningToken++;
    const token = this._warningToken;
    this.warningText.textContent = text;
    this.warningBanner.classList.add("show");
    setTimeout(() => {
      if (token === this._warningToken) this.warningBanner.classList.remove("show");
    }, duration);
  }

  hideWarning() {
    this._warningToken++;
    this.warningBanner.classList.remove("show");
  }

  showUpgrade(game, player, choices, onSelect) {
    this.upgrade.classList.remove("hidden");
    this.upgrade.setAttribute("aria-hidden", "false");
    $("upgrade-wave-cleared").textContent = String(game.wave).padStart(2, "0");
    $("upgrade-next-label").textContent = `NEXT: WAVE ${String(game.wave + 1).padStart(2, "0")}`;
    this.setUpgradeStats(game, player);
    this.selectedUpgrade = null;
    this.upgradeTip.textContent = "SELECT ONE UPGRADE";
    this.deployNextBtn.disabled = true;
    this.deployNextBtn.querySelector(".btn-label").textContent = `DEPLOY WAVE ${String(game.wave + 1).padStart(2, "0")}`;

    this.upgradeCards.innerHTML = "";
    choices.forEach((u, index) => {
      const card = document.createElement("button");
      card.type = "button";
      card.className = "upgrade-card";
      card.dataset.cat = u.cat;
      card.innerHTML = `
        <div class="upgrade-card-top">
          <span class="upgrade-cat">${u.cat}</span>
          <span class="upgrade-index">0${index + 1}</span>
        </div>
        <div class="upgrade-icon">${u.icon}</div>
        <div class="upgrade-name">${u.name}</div>
        <div class="upgrade-desc">${u.desc}</div>
        <div class="upgrade-delta">${u.delta}</div>
      `;
      card.addEventListener("click", () => {
        if (this.selectedUpgrade || game.state !== "upgrade") return;
        this.selectedUpgrade = u;
        this.upgradeCards.querySelectorAll(".upgrade-card").forEach((c) => c.classList.add("taken"));
        card.classList.remove("taken");
        card.classList.add("selected");
        this.upgradeTip.textContent = `${u.name} INSTALLED — READY TO DEPLOY`;
        this.deployNextBtn.disabled = false;
        onSelect(u);
        this.setUpgradeStats(game, player);
      });
      this.upgradeCards.appendChild(card);
    });
  }

  setUpgradeStats(game, player) {
    $("upgrade-city").textContent = `${Math.round(game.cityIntegrity)}%`;
    $("upgrade-hull").textContent = `${Math.round((player.hull / player.maxHull) * 100)}%`;
    $("upgrade-kills").textContent = game.kills;
    $("upgrade-score").textContent = Math.floor(game.score).toLocaleString("en-US");
  }

  hideUpgrade() {
    this.upgrade.classList.add("hidden");
    this.upgrade.setAttribute("aria-hidden", "true");
  }

  updatePerks(upgrades) {
    this.perksLine.innerHTML = "";
    if (!upgrades.length) {
      const span = document.createElement("span");
      span.className = "perk-chip";
      span.textContent = "STOCK AIRFRAME";
      this.perksLine.appendChild(span);
      return;
    }
    for (const u of upgrades.slice(-3)) {
      const span = document.createElement("span");
      span.className = "perk-chip";
      span.textContent = u.name;
      this.perksLine.appendChild(span);
    }
  }

  updateMute(muted) {
    const b = $("mute-btn");
    if (b) b.textContent = muted ? "SOUND OFF" : "SOUND ON";
  }

  updateClock() {
    const el = $("menu-clock");
    if (!el) return;
    const d = new Date();
    el.textContent = `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}:${String(
      d.getSeconds()
    ).padStart(2, "0")}`;
  }
}

import * as THREE from "three";

const _z = new THREE.Vector3(0, 0, 1);
const _desired = new THREE.Vector3();
const _dir = new THREE.Vector3();
const _center = new THREE.Vector3();

export class Missile {
  constructor(scene, effects, origin, direction, target, damage, turnRate) {
    this.scene = scene;
    this.effects = effects;
    this.damage = damage;
    this.turnRate = turnRate;
    this.target = target;
    this.vel = direction.clone().normalize();
    this.speed = 95;
    this.life = 6;
    this.dead = false;
    this.trailTimer = 0;

    const group = new THREE.Group();
    const bodyMat = new THREE.MeshStandardMaterial({
      color: 0x66707a,
      roughness: 0.42,
      metalness: 0.65,
    });
    const body = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.14, 1.5, 7), bodyMat);
    body.rotation.x = Math.PI / 2;
    group.add(body);
    const nose = new THREE.Mesh(
      new THREE.ConeGeometry(0.14, 0.55, 7),
      new THREE.MeshStandardMaterial({ color: 0x2f363c, roughness: 0.4, metalness: 0.75 })
    );
    nose.rotation.x = Math.PI / 2;
    nose.position.z = 1.0;
    group.add(nose);
    for (let i = 0; i < 4; i++) {
      const fin = new THREE.Mesh(
        new THREE.BoxGeometry(0.03, 0.42, 0.4),
        new THREE.MeshStandardMaterial({ color: 0x252b31, roughness: 0.55, metalness: 0.4 })
      );
      fin.position.z = -0.55;
      fin.rotation.z = (i * Math.PI) / 2;
      fin.position.x = Math.cos((i * Math.PI) / 2) * 0.18;
      fin.position.y = Math.sin((i * Math.PI) / 2) * 0.18;
      group.add(fin);
    }
    const flame = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: effects.texture,
        color: 0xffb25e,
        transparent: true,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      })
    );
    flame.position.z = -1.1;
    flame.scale.setScalar(1.9);
    group.add(flame);
    this.flame = flame;

    group.position.copy(origin);
    group.quaternion.setFromUnitVectors(_z, this.vel);
    scene.add(group);
    this.mesh = group;
    this.origin = origin;
  }

  update(dt, entities) {
    if (this.dead) return null;
    this.life -= dt;
    if (this.life <= 0) return "expire";

    if (this.target && !this.target.dead) {
      _center.copy(this.target.center);
      _desired.subVectors(_center, this.mesh.position);
      const dist = _desired.length();
      if (dist < Math.max(7, this.target.radius * 0.55)) return "hit";
      _desired.multiplyScalar(1 / Math.max(0.001, dist));
      const before = this.vel.clone();
      this.vel.lerp(_desired, Math.min(1, dt * this.turnRate)).normalize();
      // keep the missile from snapping too violently
      if (before.angleTo(this.vel) > 0.28) {
        this.vel.lerpVectors(before, this.vel, 0.4).normalize();
      }
    }

    this.mesh.position.addScaledVector(this.vel, this.speed * dt);
    this.mesh.quaternion.setFromUnitVectors(_z, this.vel);
    this.flame.material.opacity = 0.72 + Math.random() * 0.28;
    this.flame.scale.setScalar(1.55 + Math.random() * 0.7);

    this.trailTimer -= dt;
    if (this.trailTimer <= 0) {
      this.trailTimer = 0.024;
      this.effects.missileTrail(this.mesh.position);
    }

    if (this.mesh.position.y < 2.2) return "ground";
    if (Math.abs(this.mesh.position.x) > 300 || Math.abs(this.mesh.position.z) > 300) return "expire";

    // proximity fuse against non-locked targets
    for (const e of entities) {
      if (e.dead) continue;
      const d = this.mesh.position.distanceTo(e.center);
      if (d < Math.min(e.radius * 0.72, 11)) return "hit";
    }
    return null;
  }

  dispose() {
    this.dead = true;
    this.scene.remove(this.mesh);
    this.mesh.traverse((o) => {
      if (o.geometry) o.geometry.dispose();
      if (o.material && o.material !== this.effects.texture && !Array.isArray(o.material)) {
        if (!o.material.map || o.material.map !== this.effects.texture) o.material.dispose();
      }
    });
  }
}

export class EnemyOrb {
  constructor(scene, effects, origin, direction, color = 0xff5a2d, speed = 52) {
    this.scene = scene;
    this.effects = effects;
    this.vel = direction.clone().normalize();
    this.speed = speed;
    this.life = 5.5;
    this.dead = false;
    this.trailTimer = 0;
    this.color = new THREE.Color(color);

    const group = new THREE.Group();
    const core = new THREE.Mesh(
      new THREE.IcosahedronGeometry(0.52, 1),
      new THREE.MeshBasicMaterial({ color: new THREE.Color(color).lerp(new THREE.Color("#ffffff"), 0.35) })
    );
    group.add(core);
    const glow = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: effects.texture,
        color,
        transparent: true,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        opacity: 0.95,
      })
    );
    glow.scale.setScalar(4.6);
    group.add(glow);
    this.core = core;
    this.glow = glow;

    group.position.copy(origin);
    scene.add(group);
    this.mesh = group;
  }

  update(dt, playerPos) {
    if (this.dead) return null;
    this.life -= dt;
    if (this.life <= 0) return "expire";
    this.mesh.position.addScaledVector(this.vel, this.speed * dt);
    this.core.rotation.x += dt * 4;
    this.core.rotation.y += dt * 3;
    const pulse = 0.9 + Math.sin(performance.now() / 90) * 0.12;
    this.glow.scale.setScalar(4.5 * pulse);

    this.trailTimer -= dt;
    if (this.trailTimer <= 0) {
      this.trailTimer = 0.038;
      this.effects.spark(this.mesh.position, 1, {
        speed: 1.6,
        color: this.color.clone().lerp(new THREE.Color("#ffffff"), 0.3),
        life: 0.35,
        size: 0.42,
        gravity: 0,
        drag: 2.2,
      });
    }

    if (this.mesh.position.distanceTo(playerPos) < 3.1) return "player";
    if (this.mesh.position.y < 1.6) return "ground";
    if (Math.abs(this.mesh.position.x) > 300 || Math.abs(this.mesh.position.z) > 300) return "expire";
    return null;
  }

  dispose() {
    this.dead = true;
    this.scene.remove(this.mesh);
    this.core.geometry.dispose();
    this.core.material.dispose();
    this.glow.material.dispose();
  }
}

import * as THREE from "three";
import "./styles.css";
import { CityWorld } from "./world.js";
import { Kaiju, Flyer } from "./entities.js";
import { Effects } from "./effects.js";
import { SoundEngine } from "./audio.js";
import { PlayerController } from "./player.js";
import { GameUI } from "./ui.js";
import { getUpgradeChoices } from "./upgrades.js";
import { Missile, EnemyOrb } from "./projectiles.js";

const isTouch = window.matchMedia("(pointer: coarse)").matches || navigator.maxTouchPoints > 0;
const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

class Game {
  constructor() {
    this.canvas = document.getElementById("game-canvas");
    this.renderer = new THREE.WebGLRenderer({
      canvas: this.canvas,
      antialias: true,
      powerPreference: "high-performance",
    });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, isTouch ? 1.35 : 1.6));
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.16;
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;

    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(58, window.innerWidth / window.innerHeight, 0.09, 1400);
    this.camera.rotation.order = "YXZ";
    this.camera.position.set(16, 40, 112);
    this.camera.lookAt(-12, 18, 7);
    this.scene.add(this.camera);

    this.audio = new SoundEngine();
    this.effects = new Effects(this.scene, this.camera);
    this.world = new CityWorld(this.scene, {});
    for (const b of this.world.buildings) b.mesh.userData.building = b;

    this.player = new PlayerController({
      camera: this.camera,
      canvas: this.canvas,
      world: this.world,
      effects: this.effects,
      audio: this.audio,
      isTouch,
    });
    this.ui = new GameUI();

    this.entities = [];
    this.missiles = [];
    this.orbs = [];
    this.target = null;
    this.state = "menu";
    this.time = 0;
    this.lastFrame = performance.now();
    this.clock = new THREE.Clock();
    this.pauseState = "playing";
    this.menuMouse = { x: 0, y: 0 };
    this.menuTargetMouse = { x: 0, y: 0 };
    this.menuFxTimer = 0;
    this.incomingWarned = false;
    this.menuKaiju = null;
    this.initialized = false;
    this.autoStart = sessionStorage.getItem("rotor-auto-deploy") === "1";
    try {
      sessionStorage.removeItem("rotor-auto-deploy");
    } catch {
      /* ignore */
    }

    this.game = {
      state: "menu",
      wave: 0,
      waveElapsed: 0,
      clearTimer: 0,
      score: 0,
      kills: 0,
      cityIntegrity: 100,
      combo: 1,
      comboTimer: 0,
      upgrades: [],
      entities: this.entities,
      world: this.world,
    };

    this._bindCallbacks();
    this._bindUI();
    this._bindGlobalEvents();
    this._resize();
    this._createMenuActors();
    this.ui.showMenu();
    this.camera.fov = 58;
    this.camera.updateProjectionMatrix();

    this._loop = this._loop.bind(this);
    requestAnimationFrame((t) => {
      this.lastFrame = t;
      requestAnimationFrame(this._loop);
    });

    setTimeout(() => {
      document.body.classList.remove("is-loading");
    }, 120);

    this._clockTimer = setInterval(() => this.ui.updateClock(), 1000);
    this.ui.updateClock();
    this.ui.updateMute(this.audio.muted);

    if (this.autoStart) {
      setTimeout(() => this.startMission(true), 750);
    }
  }

  _bindCallbacks() {
    this.player.setCallbacks({
      onShot: (origin, dir, stats) => this._handleShot(origin, dir, stats),
      onMissile: (origin, dir, target, damage, turn) => this._spawnMissile(origin, dir, target, damage, turn),
      onOverheat: () => {
        this.ui.showWarning("VULCAN OVERHEAT", 1700);
        this.ui.feed("<b>WARNING</b> BARREL OVERHEAT", "danger");
      },
      onHeatReady: () => this.ui.feed("VULCAN <b>READY</b>", "ok"),
      onMissileReload: (count) => {
        if (count === this.player.stats.missileCap) this.ui.feed("HELLFIRE <b>RELOADED</b>", "ok");
      },
      onNoMissiles: () => this.ui.showWarning("MISSILE RACK EMPTY", 1300),
      onDamage: (amount, hull) => {
        this.ui.damageFlash(amount > 16);
        this.audio.playerHit();
        this.player.addShake(0.018);
        this.player.lastDamageAt = this.time;
        if (hull > 0 && hull / this.player.maxHull < 0.25 && !this._hullWarningShown) {
          this._hullWarningShown = true;
          this.ui.showWarning("HULL CRITICAL", 2500);
          this.audio.alarm();
        }
      },
      onDeath: () => this.gameOver("airframe"),
      onPointerLockChange: (locked) => {
        if (!locked && this.state === "playing" && this.time > 2.2) this.pauseGame();
      },
    });

    this.player.cockpit.hide();
  }

  _bindUI() {
    document.getElementById("start-btn").addEventListener("click", () => {
      this.audio.uiClick();
      this.player.requestPointerLock();
      this.startMission();
    });
    document.getElementById("briefing-btn").addEventListener("click", () => {
      this.audio.uiClick();
      this.ui.showBriefing();
    });
    document.getElementById("brief-close").addEventListener("click", () => {
      this.audio.uiClick();
      this.ui.hideBriefing();
    });
    this.ui.briefing.addEventListener("click", (e) => {
      if (e.target === this.ui.briefing) this.ui.hideBriefing();
    });

    document.getElementById("mute-btn").addEventListener("click", () => {
      this.audio.init();
      const muted = this.audio.toggleMute();
      this.ui.updateMute(muted);
    });

    document.getElementById("deploy-next-btn").addEventListener("click", () => {
      if (this.state !== "upgrade") return;
      this.audio.uiClick();
      this.audio.init();
      this.ui.hideUpgrade();
      this.state = "playing";
      this.game.state = "playing";
      this.player.start();
      this.player.requestPointerLock();
      this.spawnWave(this.game.wave + 1);
    });

    document.getElementById("resume-btn").addEventListener("click", () => this.resumeGame());
    document.getElementById("quit-btn").addEventListener("click", () => {
      this.audio.uiClick();
      this._reloadToMenu();
    });
    document.getElementById("retry-btn").addEventListener("click", () => {
      this.audio.uiClick();
      try {
        sessionStorage.setItem("rotor-auto-deploy", "1");
      } catch {
        /* ignore */
      }
      this.ui.setTransition(true);
      this.state = "transition";
      setTimeout(() => window.location.reload(), 420);
    });
    document.getElementById("menu-btn").addEventListener("click", () => {
      this.audio.uiClick();
      this._reloadToMenu();
    });

    window.addEventListener(
      "pointerdown",
      () => {
        if (this.audio.ctx && this.audio.ctx.state === "suspended") this.audio.ctx.resume();
      },
      { passive: true }
    );
  }

  _bindGlobalEvents() {
    window.addEventListener("resize", () => this._resize());

    window.addEventListener("keydown", (e) => {
      if (e.code === "KeyM" && !e.repeat) {
        this.audio.init();
        this.ui.updateMute(this.audio.toggleMute());
      }
      if (e.code === "Escape") {
        if (this.state === "playing" || this.state === "clearing") {
          e.preventDefault();
          this.pauseGame();
        } else if (this.state === "paused") {
          e.preventDefault();
          this.resumeGame();
        } else if (this.ui.briefing.classList.contains("hidden") === false) {
          this.ui.hideBriefing();
        }
      }
    });

    document.addEventListener("visibilitychange", () => {
      if (document.hidden && (this.state === "playing" || this.state === "clearing")) {
        this.pauseGame();
      }
    });

    window.addEventListener("pointermove", (e) => {
      if (this.state !== "menu") return;
      this.menuTargetMouse.x = (e.clientX / window.innerWidth) * 2 - 1;
      this.menuTargetMouse.y = (e.clientY / window.innerHeight) * 2 - 1;
    });

    this.canvas.addEventListener("click", () => {
      if (this.state === "playing" && !isTouch && document.pointerLockElement !== this.canvas) {
        this.player.requestPointerLock();
      }
    });
  }

  _resize() {
    const w = window.innerWidth;
    const h = window.innerHeight;
    this.camera.aspect = w / h;
    this.camera.updateProjectionMatrix();
    this.renderer.setSize(w, h);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, isTouch ? 1.35 : 1.6));
    this.effects.setScale(h);
  }

  _createMenuActors() {
    this._removeMenuActors();
    this.menuKaiju = new Kaiju(this.scene, null, "behemoth", new THREE.Vector3(-1, 0, 15), 1);
    this.menuKaiju.root.rotation.y = 0;
    this.menuKaiju.attackCooldown = 9999;
    this.menuKaiju.speed = 0;
    this.menuDummyPlayer = new THREE.Vector3(20, 28, 15);
    this.menuFxTimer = 0.2;
  }

  _removeMenuActors() {
    if (this.menuKaiju) {
      this.scene.remove(this.menuKaiju.root);
      this.menuKaiju = null;
    }
  }

  startMission(auto = false) {
    if (this.state !== "menu") return;
    this.audio.init();
    if (!auto && !isTouch) this.player.requestPointerLock();
    this.ui.hideBriefing();
    this.state = "transition";
    this.game.state = "transition";
    this.ui.setTransition(true);

    setTimeout(() => {
      this.ui.hideMenu();
      this.ui.showHud();
      this._removeMenuActors();
      this.camera.fov = 70;
      this.camera.updateProjectionMatrix();
      this.resetRun();
      this.player.start();
      this.state = "playing";
      this.game.state = "playing";
      this.spawnWave(1);
      this.ui.setTransition(false);
      if (isTouch) {
        const hint = document.getElementById("look-hint");
        if (hint) {
          hint.classList.add("show");
          setTimeout(() => hint.classList.remove("show"), 5200);
        }
      }
    }, 460);
  }

  resetRun() {
    for (const e of this.entities) this.scene.remove(e.root);
    this.entities.length = 0;
    for (const m of this.missiles) m.dispose();
    this.missiles.length = 0;
    for (const o of this.orbs) o.dispose();
    this.orbs.length = 0;
    this.target = null;
    this.player.resetRun();
    this.player.target = null;
    this.player.cockpit.hide();
    this.player.cockpit.show();
    this.game.wave = 0;
    this.game.score = 0;
    this.game.kills = 0;
    this.game.cityIntegrity = 100;
    this.game.waveElapsed = 0;
    this.game.clearTimer = 0;
    this.game.combo = 1;
    this.game.comboTimer = 0;
    this.game.upgrades = [];
    this.game.entities = this.entities;
    this.game.world = this.world;
    this.game.state = "playing";
    this._hullWarningShown = false;
    this.ui.resetHud();
    this.ui.updatePerks([]);
    this.ui.updateMute(this.audio.muted);
  }

  spawnWave(wave) {
    // clear the dead and any stragglers
    for (const e of this.entities) this.scene.remove(e.root);
    this.entities.length = 0;
    for (const m of this.missiles) m.dispose();
    this.missiles.length = 0;
    for (const o of this.orbs) o.dispose();
    this.orbs.length = 0;
    this.target = null;
    this.player.target = null;

    this.game.wave = wave;
    this.game.waveElapsed = 0;
    this.game.clearTimer = 0;
    this.game.combo = 1;
    this.game.comboTimer = 0;
    this.game.state = "playing";
    this.state = "playing";
    this._hullWarningShown = false;

    if (wave > 1) {
      this.game.cityIntegrity = Math.min(100, this.game.cityIntegrity + 3);
      this.player.heal(9);
    }

    const kaijuCount = Math.min(4, 1 + Math.floor((wave - 1) / 2) + (wave >= 6 ? 1 : 0));
    const flyerCount = Math.min(5, wave === 1 ? 1 : 1 + Math.floor(wave / 2));
    const spawns = [
      new THREE.Vector3(0, 0, 20),
      new THREE.Vector3(-54, 0, -46),
      new THREE.Vector3(54, 0, -108),
      new THREE.Vector3(0, 0, -168),
    ];

    for (let i = 0; i < kaijuCount; i++) {
      let type = i % 2 === 0 ? "behemoth" : "ravager";
      if (wave % 4 === 0 && i === 0) type = "colossus";
      const pos = spawns[i].clone();
      pos.z += (wave % 3) * 4;
      const kaiju = new Kaiju(this.scene, this.world, type, pos, wave);
      kaiju.speed = kaiju.cfg.speed * (1 + Math.min(0.35, wave * 0.022));
      kaiju.onBuildingHit = (building, destroyed, hitPos) => this._handleBuildingHit(building, destroyed, hitPos);
      this.entities.push(kaiju);
    }

    const flyerTypes = ["ashwing", "nightwing"];
    for (let i = 0; i < flyerCount; i++) {
      const angle = Math.random() * Math.PI * 2;
      const radius = 90 + Math.random() * 65;
      const pos = new THREE.Vector3(
        this.player.pos.x + Math.cos(angle) * radius,
        48 + Math.random() * 30,
        this.player.pos.z + Math.sin(angle) * radius
      );
      const type = flyerTypes[wave >= 3 ? i % 2 : 0];
      const flyer = new Flyer(this.scene, type, pos, wave);
      flyer.orbitRadius = 38 + Math.random() * 38;
      flyer.fireCallback = (source, mouth, targetPos, color) =>
        this._spawnEnemyOrb(source, mouth, targetPos, color);
      this.entities.push(flyer);
    }

    const total = this.entities.length;
    const bossWave = wave % 4 === 0;
    this.ui.showBanner(
      `WAVE ${String(wave).padStart(2, "0")}`,
      bossWave ? "OMEGA BREACH" : "BREACH DETECTED",
      `${String(total).padStart(2, "0")} HOSTILES // SECTOR 07`,
      3200
    );
    this.ui.feed(`<b>WAVE ${String(wave).padStart(2, "0")}</b> CONTACT IN SECTOR 07`);
    this.ui.showWarning(bossWave ? "CLASS VI KAIJU DETECTED" : "KAIJU SIGNATURES DETECTED", 2500);
    this.audio.roar(bossWave);
    this.audio.updateEngine(0, false, true);
    this.ui.updatePerks(this.game.upgrades);
  }

  _handleShot(origin, dir, stats) {
    if (this.state !== "playing") return;
    const raycaster = new THREE.Raycaster(origin, dir, 0.5, 700);
    const objects = [];
    for (const e of this.entities) {
      if (!e.dead) for (const m of e.hitMeshes) objects.push(m);
    }
    for (const b of this.world.buildings) {
      if (!b.destroyed) objects.push(b.mesh);
    }

    const hits = raycaster.intersectObjects(objects, true);
    let end = origin.clone().addScaledVector(dir, 420);
    for (const hit of hits) {
      const entity = hit.object.userData.entity;
      if (entity) {
        if (entity.dead) continue;
        const part = hit.object.userData.part || "body";
        const crit = part === "head" || Math.random() < stats.critChance;
        const damage = stats.damage * (crit ? 2.15 : 1) * (0.9 + Math.random() * 0.2);
        const result = entity.takeDamage(damage, crit);
        this.player.registerHit();
        this.ui.hitMarker(crit);
        this.audio.hit(crit);
        this.effects.hit(hit.point, entity.cfg.accent, crit);
        this.game.score += Math.round(damage * 0.13 * this.game.combo);
        this.game.combo = Math.min(9, this.game.combo + 1);
        this.game.comboTimer = 2.6;
        end = hit.point.clone();
        if (result?.killed) this._handleKill(entity);
        this.effects.tracer(origin, end);
        return;
      }
      const building = hit.object.userData.building;
      if (building) {
        this.effects.spark(hit.point, 5, {
          speed: 7,
          color: new THREE.Color(0xcbd2d6),
          life: 0.3,
          size: 0.18,
          gravity: 9,
          drag: 1.4,
        });
        this.effects.tracer(origin, hit.point);
        return;
      }
    }
    this.effects.tracer(origin, end);
  }

  _handleKill(entity) {
    if (entity._killedHandled) return;
    entity._killedHandled = true;
    entity.dead = true;
    this.game.kills++;
    const isKaiju = entity.isKaiju;
    const base = isKaiju ? 900 + this.game.wave * 130 : 260 + this.game.wave * 30;
    const bonus = Math.round(base * Math.max(1, this.game.combo * 0.75));
    this.game.score += bonus;
    const pos = entity.center.clone();
    const color = entity.cfg.accent;
    const name = entity.cfg.name;

    if (isKaiju) {
      this.effects.explosion(pos, entity.type === "colossus" ? 3.2 : 2.1, color);
      this.effects.buildingCollapse(pos.clone().setY(8), entity.type === "colossus" ? 45 : 30);
      this.audio.explosion(entity.type === "colossus" ? 1.8 : 1.15);
      this.player.addShake(entity.type === "colossus" ? 0.065 : 0.032);
      this.world.flash(pos, 18);
      this.ui.showWarning(`${name} DOWN`, 1900);
      const extra = entity.type === "colossus" ? 3 : 1;
      for (let i = 0; i < extra; i++) {
        setTimeout(() => {
          if (!entity.root.parent) return;
          const p = entity.center.clone();
          p.x += (Math.random() - 0.5) * 8;
          p.z += (Math.random() - 0.5) * 8;
          p.y = 6 + Math.random() * 13;
          this.effects.explosion(p, 1.5, color);
          this.audio.explosion(1.0);
          this.world.flash(p, 10);
        }, 420 + i * 430);
      }
      this.ui.feed(`<b>+${bonus}</b> KAIJU NEUTRALIZED // ${name}`);
    } else {
      this.effects.explosion(pos, 1.25, color);
      this.audio.explosion(0.8);
      this.player.addShake(0.008);
      this.ui.feed(`<b>+${bonus}</b> AIRBORNE KILL // ${name}`);
    }

    if (this.player.stats.repairPerKill > 0) {
      const healed = this.player.heal(this.player.stats.repairPerKill);
      if (healed > 0) this.ui.feed(`NANO-FORGE <b>+${Math.round(healed)} HULL</b>`, "ok");
    }

    if (this.game.combo >= 4) {
      this.ui.feed(`<b>x${this.game.combo}</b> KILL CHAIN`, "ok");
    }
    this.ui.updatePlayHud(this.game, this.player);
  }

  _handleBuildingHit(building, destroyed, pos) {
    this.game.cityIntegrity = Math.max(0, this.game.cityIntegrity - (destroyed ? 5.5 : 1.7));
    this.player.addShake(destroyed ? 0.032 : 0.011);
    this.effects.smokePuff(pos, destroyed ? 36 : 10, {
      speed: destroyed ? 6 : 3,
      life: destroyed ? 4 : 2.2,
      size: destroyed ? 2.8 : 1.5,
      color: new THREE.Color("#5c5b59"),
      alpha: 0.42,
    });
    this.effects.spark(pos, destroyed ? 24 : 8, {
      speed: destroyed ? 18 : 8,
      color: new THREE.Color("#ff9b52"),
      life: 0.8,
      size: 0.55,
      gravity: 13,
    });
    if (destroyed) {
      this.effects.buildingCollapse(new THREE.Vector3(building.x, 0, building.z), building.height);
      this.audio.explosion(1.2);
      this.world.flash(new THREE.Vector3(building.x, 18, building.z), 15);
      this.ui.feed("<b>CIVILIAN BLOCK LOST</b> CITY INTEGRITY -5%", "danger");
      this.ui.damageFlash(true);
    } else {
      this.audio.explosion(0.36);
    }
    if (this.game.cityIntegrity <= 0 && this.state === "playing") this.gameOver("city");
  }

  _spawnMissile(origin, dir, target, damage, turn) {
    const missile = new Missile(this.scene, this.effects, origin, dir, target, damage, turn);
    this.missiles.push(missile);
    this.ui.feed("<b>HELLFIRE</b> AWAY", "ok");
  }

  _spawnEnemyOrb(source, mouth, targetPos, color) {
    const lead = Math.min(0.8, mouth.distanceTo(targetPos) / 80);
    const aim = targetPos.clone().addScaledVector(this.player.vel, lead * 0.35);
    aim.x += (Math.random() - 0.5) * 3.5;
    aim.y += (Math.random() - 0.5) * 2.5;
    aim.z += (Math.random() - 0.5) * 3.5;
    const dir = aim.sub(mouth).normalize();
    const orb = new EnemyOrb(this.scene, this.effects, mouth, dir, color, 52 + this.game.wave * 2.4);
    this.orbs.push(orb);
    this.audio.enemyShot();
  }

  _updateMissiles(dt) {
    for (let i = this.missiles.length - 1; i >= 0; i--) {
      const m = this.missiles[i];
      const result = m.update(dt, this.entities);
      if (!result) continue;
      this._explodeMissile(m, result);
      m.dispose();
      this.missiles.splice(i, 1);
    }
  }

  _explodeMissile(missile, result) {
    const pos = missile.mesh.position.clone();
    this.effects.explosion(pos, 2.2, 0xff8a45);
    this.effects.debrisBurst(pos, 12, 0.8);
    this.audio.explosion(1.25);
    this.world.flash(pos, 13);
    const dist = this.player.pos.distanceTo(pos);
    if (dist < 110) this.player.addShake(0.035 * (1 - dist / 110));

    let mainTarget = missile.target;
    if (!mainTarget || mainTarget.dead) {
      let best = null;
      let bestD = 30;
      for (const e of this.entities) {
        if (e.dead) continue;
        const d = e.center.distanceTo(pos);
        if (d < bestD) {
          bestD = d;
          best = e;
        }
      }
      mainTarget = best;
    }
    if (mainTarget && !mainTarget.dead && mainTarget.center.distanceTo(pos) < 30) {
      const res = mainTarget.takeDamage(missile.damage, true);
      this.player.registerHit();
      this.ui.hitMarker(true);
      this.game.score += Math.round(missile.damage * 0.16 * this.game.combo);
      if (res?.killed) this._handleKill(mainTarget);
    }
    for (const e of this.entities) {
      if (e.dead || e === mainTarget) continue;
      if (e.center.distanceTo(pos) < 22) {
        const res = e.takeDamage(missile.damage * 0.32, false);
        if (res?.killed) this._handleKill(e);
      }
    }
    if (result === "expire") {
      this.effects.smokePuff(pos, 5, {
        speed: 1.6,
        life: 1.2,
        size: 1.1,
        alpha: 0.2,
      });
    }
  }

  _updateOrbs(dt) {
    for (let i = this.orbs.length - 1; i >= 0; i--) {
      const orb = this.orbs[i];
      const result = orb.update(dt, this.player.pos);
      if (!result) continue;
      const pos = orb.mesh.position.clone();
      if (result === "player") {
        this.effects.explosion(pos, 0.8, orb.color.getHex());
        this.player.damage(8 + this.game.wave * 1.1, "plasma");
        this.ui.damageFlash(false);
      } else if (result === "ground") {
        this.effects.explosion(pos, 0.55, orb.color.getHex());
        if (pos.distanceTo(this.player.pos) < 35) this.player.addShake(0.004);
      }
      orb.dispose();
      this.orbs.splice(i, 1);
    }

    const threat = this.orbs.some((o) => o.mesh.position.distanceTo(this.player.pos) < 48);
    if (threat && !this.incomingWarned) {
      this.incomingWarned = true;
      this.ui.showWarning("PLASMA INBOUND", 1200);
    } else if (!threat) {
      this.incomingWarned = false;
    }
  }

  _updateTarget() {
    if (this.state !== "playing" && this.state !== "clearing") {
      this.target = null;
      this.player.target = null;
      return;
    }
    const forward = new THREE.Vector3();
    this.camera.getWorldDirection(forward);
    let best = null;
    let bestScore = Infinity;
    const tmp = new THREE.Vector3();

    for (const e of this.entities) {
      if (e.dead) continue;
      tmp.copy(e.center);
      const dist = this.camera.position.distanceTo(tmp);
      if (dist > 520) continue;
      const dirTo = tmp.clone().sub(this.camera.position).normalize();
      const dot = dirTo.dot(forward);
      if (dot < 0.55) continue;
      const ndc = tmp.clone().project(this.camera);
      if (ndc.z < -1 || ndc.z > 1) continue;
      const score = Math.hypot(ndc.x, ndc.y);
      const limit = e.isFlyer ? 0.16 : 0.28;
      if (score < limit && score < bestScore) {
        bestScore = score;
        best = e;
      }
    }

    this.target = best;
    this.player.target = best;
  }

  _updateEntities(dt) {
    for (let i = this.entities.length - 1; i >= 0; i--) {
      const e = this.entities[i];
      e.update(dt, this.time, this.player.pos);
      if (e.remove) {
        this.scene.remove(e.root);
        this.entities.splice(i, 1);
      }
    }
  }

  _beginWaveClear() {
    if (this.state !== "playing") return;
    this.state = "clearing";
    this.game.state = "clearing";
    this.game.clearTimer = 2.7;
    this.game.score += 500 + this.game.wave * 210;
    this.player.firing = false;
    this.player.heal(8);
    this.game.cityIntegrity = Math.min(100, this.game.cityIntegrity + 2.5);
    this.target = null;
    this.player.target = null;
    this.ui.showBanner("SECTOR 07", "AREA SECURED", "CIVIL DEFENSE CREWS MOVING IN", 2600);
    this.ui.feed("<b>SECTOR CLEAR</b> SALVAGE SECURED", "ok");
    this.audio.upgrade();
  }

  _openUpgrade() {
    if (this.state !== "clearing") return;
    this.state = "upgrade";
    this.game.state = "upgrade";
    this.player.stop();
    this.audio.updateEngine(0, false, false);
    try {
      document.exitPointerLock?.();
    } catch {
      /* ignore */
    }
    const choices = getUpgradeChoices();
    this.ui.showUpgrade(this.game, this.player, choices, (u) => {
      u.apply(this.player);
      this.player.applyStats();
      this.game.upgrades.push(u);
      this.ui.updatePerks(this.game.upgrades);
      this.audio.upgrade();
    });
  }

  _updatePlaying(dt) {
    this.player.update(dt, this.time);
    this._updateTarget();
    this._updateEntities(dt);
    this._updateMissiles(dt);
    this._updateOrbs(dt);

    if (this.state === "playing") {
      this.game.waveElapsed += dt;
      this.game.comboTimer -= dt;
      if (this.game.comboTimer <= 0 && this.game.combo > 1) {
        this.game.combo = 1;
      }
      const allDead = this.entities.length > 0 && this.entities.every((e) => e.dead);
      if (allDead) this._beginWaveClear();
      if (this.entities.length === 0) {
        // protection against a wave with no spawns
        this._beginWaveClear();
      }
    } else if (this.state === "clearing") {
      this.game.comboTimer -= dt;
      this.game.clearTimer -= dt;
      this.player.firing = false;
      if (this.game.clearTimer <= 0) this._openUpgrade();
    }

    this.ui.updatePlayHud(this.game, this.player);
    this.ui.updateTarget(this.target, this.player);
  }

  _updateMenu(dt) {
    this.menuMouse.x += (this.menuTargetMouse.x - this.menuMouse.x) * Math.min(1, dt * 2.2);
    this.menuMouse.y += (this.menuTargetMouse.y - this.menuMouse.y) * Math.min(1, dt * 2.2);
    const t = this.time;
    const driftX = this.menuMouse.x * 3.2;
    const driftY = this.menuMouse.y * 1.8;
    this.camera.position.x = 16 + Math.sin(t * 0.08) * 1.1 + driftX;
    this.camera.position.y = 40 + Math.sin(t * 0.17) * 0.55 - driftY * 0.5;
    this.camera.position.z = 112 + Math.cos(t * 0.06) * 1.2;
    this.camera.lookAt(-12 + this.menuMouse.x * 2.2, 18 - this.menuMouse.y * 1.2, 7);
    this.camera.updateMatrixWorld();

    if (this.menuKaiju) {
      this.menuKaiju.update(dt, t, this.menuDummyPlayer || this.player.pos);
      this.menuKaiju.root.rotation.y = Math.sin(t * 0.12) * 0.06;
    }

    this.menuFxTimer -= dt;
    if (this.menuFxTimer <= 0) {
      this.menuFxTimer = 1.6 + Math.random() * 1.8;
      const p = new THREE.Vector3((Math.random() - 0.5) * 65, 3 + Math.random() * 11, 5 + (Math.random() - 0.5) * 68);
      this.effects.smokePuff(p, 5, {
        speed: 2.2,
        life: 4.5,
        size: 2.5,
        color: new THREE.Color("#4b4a48"),
        alpha: 0.27,
        gravity: -0.4,
        rise: 1.2,
      });
      this.effects.spark(p, 4, {
        speed: 4,
        color: new THREE.Color("#ff7e3d"),
        life: 1.2,
        size: 0.5,
        gravity: 1,
      });
      this.world.flash(p, 5);
      if (Math.random() < 0.35) this.effects.explosion(p, 0.5, 0xff6a2e);
    }
  }

  pauseGame() {
    if (this.state !== "playing" && this.state !== "clearing") return;
    this.pauseState = this.state;
    this.state = "paused";
    this.game.state = "paused";
    this.player.stop();
    this.audio.updateEngine(0, false, false);
    this.ui.hideWarning();
    this.ui.showPause();
    try {
      document.exitPointerLock?.();
    } catch {
      /* ignore */
    }
  }

  resumeGame() {
    if (this.state !== "paused") return;
    this.audio.init();
    this.audio.uiClick();
    this.state = this.pauseState;
    this.game.state = this.pauseState;
    this.ui.hidePause();
    this.player.start();
    this.player.requestPointerLock();
    this.audio.updateEngine(this.player.vel.length(), false, true);
  }

  gameOver(reason) {
    if (this.state === "gameover" || this.state === "transition") return;
    this.state = "gameover";
    this.game.state = "gameover";
    this.player.stop();
    this.audio.updateEngine(0, false, false);
    this.audio.explosion(reason === "city" ? 1.5 : 2);
    try {
      document.exitPointerLock?.();
    } catch {
      /* ignore */
    }
    const cleared = Math.max(0, this.game.wave - 1);
    const newBest = this.ui.saveBest(Math.floor(this.game.score), cleared);
    this.ui.showGameOver(reason, this.game, this.player, newBest);
    this.ui.hideWarning();
    this.target = null;
    this.player.target = null;
  }

  _reloadToMenu() {
    this.ui.setTransition(true);
    this.state = "transition";
    setTimeout(() => window.location.reload(), 420);
  }

  _loop(now) {
    const dt = Math.min(0.05, Math.max(0, (now - this.lastFrame) / 1000));
    this.lastFrame = now;
    this.time += dt;

    this.world.update(dt, this.time);
    this.effects.update(dt, this.time);

    if (this.state === "menu") {
      this._updateMenu(dt);
    } else if (this.state === "playing" || this.state === "clearing") {
      this._updatePlaying(dt);
    }

    this.renderer.render(this.scene, this.camera);
    requestAnimationFrame(this._loop);
  }
}

window.addEventListener("error", (event) => {
  console.error("ROTOR//TITAN runtime error", event.error || event.message);
});

const boot = () => {
  try {
    window.__rotorGame = new Game();
  } catch (err) {
    console.error(err);
    document.body.classList.remove("is-loading");
  }
};

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", boot);
} else {
  boot();
}

