import { chromium } from "/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core/index.mjs";

const url = process.argv[2] || "http://localhost:3002";
const prefix = process.argv[3] || "screenshots/game";
const width = Number(process.argv[4] || 1440);
const height = Number(process.argv[5] || 900);

const browser = await chromium.launch({
  headless: false,
  env: { ...process.env, DISPLAY: ":0" },
  args: [
    "--enable-gpu",
    "--ignore-gpu-blocklist",
    "--use-angle=vulkan",
    "--use-vulkan=swiftshader",
    "--disable-vulkan-surface",
    "--no-sandbox",
  ],
});
const page = await browser.newPage({ viewport: { width, height }, deviceScaleFactor: 1 });
page.on("console", (msg) => {
  if (msg.type() === "error" || msg.type() === "warning") console.log("CONSOLE", msg.type(), msg.text().slice(0, 300));
});
page.on("pageerror", (err) => console.log("PAGEERROR", err.message));
await page.goto(url, { waitUntil: "load", timeout: 120000 });
await page.waitForTimeout(2500);
await page.screenshot({ path: `${prefix}-menu.png`, timeout: 120000 });
console.log("SHOT", `${prefix}-menu.png`);

await page.evaluate(() => {
  const g = window.__rotorGame;
  g.ui.setTransition(false);
  g.startMission(true);
});
await page.waitForTimeout(5000);
await page.screenshot({ path: `${prefix}-play.png`, timeout: 120000 });
console.log("SHOT", `${prefix}-play.png`);

await page.evaluate(() => {
  const g = window.__rotorGame;
  g.player.firing = true;
});
await page.waitForTimeout(1800);
await page.evaluate(() => {
  const g = window.__rotorGame;
  g.player.firing = false;
});
await page.screenshot({ path: `${prefix}-fire.png`, timeout: 120000 });
console.log("SHOT", `${prefix}-fire.png`);

await page.evaluate(() => {
  const g = window.__rotorGame;
  // aim at first entity by snapping camera toward it
  const e = g.entities.find((x) => !x.dead && x.isKaiju) || g.entities[0];
  if (e) {
    const p = e.center.clone();
    g.camera.lookAt(p);
    g.target = e;
    g.player.target = e;
  }
});
await page.waitForTimeout(1200);
await page.screenshot({ path: `${prefix}-aim.png`, timeout: 120000 });
console.log("SHOT", `${prefix}-aim.png`);

await page.evaluate(() => {
  const g = window.__rotorGame;
  g.pauseGame();
});
await page.waitForTimeout(600);
await page.screenshot({ path: `${prefix}-pause.png`, timeout: 120000 });
console.log("SHOT", `${prefix}-pause.png`);

await page.evaluate(() => {
  const g = window.__rotorGame;
  g.resumeGame();
  // force wave clear -> upgrade
  for (const e of g.entities) { e.dead = true; }
});
await page.waitForTimeout(4200);
await page.screenshot({ path: `${prefix}-upgrade.png`, timeout: 120000 });
console.log("SHOT", `${prefix}-upgrade.png`);

await page.evaluate(() => {
  const g = window.__rotorGame;
  g.game.score = 124500;
  g.game.kills = 23;
  g.game.cityIntegrity = 4;
  g.gameOver("city");
});
await page.waitForTimeout(700);
await page.screenshot({ path: `${prefix}-gameover.png`, timeout: 120000 });
console.log("SHOT", `${prefix}-gameover.png`);

await browser.close();

