const browser = await chromium.launch({ headless: false, env: { ...process.env, DISPLAY: ":0" }, args: ["--use-angle=vulkan","--use-vulkan=swiftshader","--disable-vulkan-surface","--no-sandbox"] });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
page.on("console", (m) => { if (m.type() === "error") console.log("CONSOLE", m.text().slice(0,200)); });
await page.goto("http://localhost:3002", { waitUntil: "load" });
await page.waitForTimeout(2000);
await page.evaluate(() => { const g = window.__rotorGame; g.ui.setTransition(false); g.startMission(true); });
await page.waitForTimeout(3000);
for (let i = 0; i < 10; i++) {
  const st = await page.evaluate(() => {
    const g = window.__rotorGame;
    return { state: g.state, gstate: g.game.state, clear: +g.game.clearTimer.toFixed(2), ent: g.entities.length, dead: g.entities.filter(e=>e.dead).length, upHidden: g.ui.upgrade.classList.contains("hidden") };
  });
  console.log(i, JSON.stringify(st));
  if (i === 1) await page.evaluate(() => { const g = window.__rotorGame; for (const e of g.entities) e.dead = true; });
  await page.waitForTimeout(700);
}
await page.screenshot({ path: "screenshots/upgrade-debug.png" });
await browser.close();

