    font-size: 18px;
    margin-top: 6px;
  }
  .upgrade-desc {
    font-size: 7px;
    margin-top: 3px;
  }
  .upgrade-delta {
    grid-column: 2;
    padding-top: 5px;
  }
  .upgrade-footer {
    margin-top: 12px;
    padding-top: 10px;
    gap: 10px;
  }
  .upgrade-tip {
    display: none;
  }
  .upgrade-footer .btn {
    width: 100%;
    min-width: 0;
  }
  .combo {
    display: none;
  }
}

@media (max-height: 700px) and (min-width: 861px) {
  .menu-layout {
    padding-top: 20px;
    padding-bottom: 10px;
  }
  .logo {
    font-size: clamp(64px, 9.5vw, 122px);
  }
  .tagline {
    margin-top: 16px;
    font-size: 24px;
  }
  .deck {
    margin-top: 9px;
    font-size: 9px;
  }
  .menu-actions {
    margin-top: 17px;
  }
  .control-strip {
    margin-top: 21px;
    padding-top: 12px;
  }
  .menu-side {
    padding-bottom: 0;
    gap: 12px;
  }
  .threat-panel {
    padding: 13px;
  }
  .best-panel {
    display: none;
  }
}

@media (pointer: coarse) {
  .touch-ui {
    display: block;
  }
  .hud-footer,
  .radar-wrap {
    display: none;
  }
  .weapon-hud,
  .flight-hud {
    bottom: calc(185px + var(--safe-bottom));
  }
  .city-status {
    width: min(270px, 32vw);
  }
  .icon-btn {
    display: none;
  }
}

@media (pointer: coarse) and (orientation: portrait) {
  .touch-ui .joystick-zone {
    bottom: calc(155px + var(--safe-bottom));
  }
  .touch-ui .touch-actions {
    bottom: calc(150px + var(--safe-bottom));
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

