import { chromium } from "/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core/index.mjs";

const browser = await chromium.launch({
  headless: false,
  env: { ...process.env, DISPLAY: ":0" },
  args: [
    "--enable-gpu", "--ignore-gpu-blocklist", "--use-angle=vulkan",
    "--use-vulkan=swiftshader", "--disable-vulkan-surface", "--no-sandbox",
  ],
});
const ctx = await browser.newContext({
  viewport: { width: 390, height: 844 },
  hasTouch: true,
  isMobile: true,
  deviceScaleFactor: 1,
});
const page = await ctx.newPage();
page.on("pageerror", (e) => console.log("PAGEERROR", e.message));
await page.goto("http://localhost:3002", { waitUntil: "load", timeout: 120000 });
await page.waitForTimeout(6500);

const cdp = await ctx.newCDPSession(page);
const touch = async (type, points) =>
  cdp.send("Input.dispatchTouchEvent", { type, touchPoints: points });

const box = async (sel) => page.locator(sel).boundingBox();

// Start via real tap on deploy
const start = await box("#start-btn");
await touch("touchStart", [{ x: start.x + start.width / 2, y: start.y + start.height / 2, id: 1 }]);
await touch("touchEnd", []);
await page.waitForTimeout(5000);

let st = await page.evaluate(() => {
  const g = window.__rotorGame;
  return g ? { state: g.state, enabled: g.player.enabled, touch: g.isTouch } : null;
});
console.log("after deploy:", JSON.stringify(st));

await page.evaluate(() => document.body.classList.add("touch-test"));

// --- Joystick forward ---
const zone = await box("#joystick-zone");
const zx = zone.x + zone.width / 2;
const zy = zone.y + zone.height / 2;
const before = await page.evaluate(() => {
  const g = window.__rotorGame;
  return { pos: g.player.pos.toArray(), vel: g.player.vel.toArray(), alt: g.player.altitude };
});
await touch("touchStart", [{ x: zx, y: zy, id: 2 }]);
await touch("touchMove", [{ x: zx, y: zy - 44, id: 2 }]);
await page.waitForTimeout(1800);
const stick = await page.evaluate(() => {
  const g = window.__rotorGame;
  return { move: { ...g.player.touchMove }, pos: g.player.pos.toArray(), vel: g.player.vel.toArray() };
});
await touch("touchEnd", []);
console.log("joystick before:", JSON.stringify(before));
console.log("joystick after :", JSON.stringify(stick));

// --- Look drag on canvas ---
const look0 = await page.evaluate(() => {
  const p = window.__rotorGame.player;
  return { yaw: p.yaw, pitch: p.pitch };
});
await touch("touchStart", [{ x: 195, y: 330, id: 3 }]);
await touch("touchMove", [{ x: 245, y: 355, id: 3 }]);
await page.waitForTimeout(250);
await touch("touchEnd", []);
const look1 = await page.evaluate(() => {
  const p = window.__rotorGame.player;
  return { yaw: p.yaw, pitch: p.pitch };
});
console.log("look before:", JSON.stringify(look0), "after:", JSON.stringify(look1));

// --- Fire hold ---
const fire = await box("#touch-fire");
const fx = fire.x + fire.width / 2;
const fy = fire.y + fire.height / 2;
const shots0 = await page.evaluate(() => window.__rotorGame.player.shots);
await touch("touchStart", [{ x: fx, y: fy, id: 4 }]);
await page.waitForTimeout(1400);
const firing = await page.evaluate(() => ({ firing: window.__rotorGame.player.firing, shots: window.__rotorGame.player.shots }));
await touch("touchEnd", []);
console.log("fire: before shots", shots0, "->", JSON.stringify(firing));

// --- Missile tap ---
const msl = await box("#touch-missile");
const mx = msl.x + msl.width / 2;
const my = msl.y + msl.height / 2;
const m0 = await page.evaluate(() => ({ missiles: window.__rotorGame.player.missiles, shots: window.__rotorGame.player.shots }));
await touch("touchStart", [{ x: mx, y: my, id: 5 }]);
await touch("touchEnd", []);
await page.waitForTimeout(600);
const m1 = await page.evaluate(() => ({ missiles: window.__rotorGame.player.missiles, shots: window.__rotorGame.player.shots }));
console.log("missile: before", JSON.stringify(m0), "after", JSON.stringify(m1));

// --- Altitude down hold ---
const down = await box("#touch-down");
const dx = down.x + down.width / 2;
const dy = down.y + down.height / 2;
const a0 = await page.evaluate(() => window.__rotorGame.player.altitude);
await touch("touchStart", [{ x: dx, y: dy, id: 6 }]);
await page.waitForTimeout(1600);
const altDuring = await page.evaluate(() => ({ alt: window.__rotorGame.player.altitude, touchAlt: window.__rotorGame.player.touchAlt }));
await touch("touchEnd", []);
console.log("altitude down: before", a0.toFixed(1), "during", JSON.stringify(altDuring));

// --- Altitude up hold ---
const up = await box("#touch-up");
const ux = up.x + up.width / 2;
const uy = up.y + up.height / 2;
await touch("touchStart", [{ x: ux, y: uy, id: 7 }]);
await page.waitForTimeout(1600);
const altUp = await page.evaluate(() => ({ alt: window.__rotorGame.player.altitude, touchAlt: window.__rotorGame.player.touchAlt }));
await touch("touchEnd", []);
console.log("altitude up: ", JSON.stringify(altUp));

await page.screenshot({ path: "screenshots/touch-test.png", timeout: 120000 });
await browser.close();

